import hashlib
import os
import tempfile
import shelve

class FileHasher:
    _cached_hashes = shelve.open('cached_hashes', writeback=True)

    @staticmethod
    def _calculate_hash(path):
        with open(path, 'rb') as f:
            return hashlib.md5(f.read()).hexdigest()

    @classmethod
    def get_hash(cls, path):
        if path in cls._cached_hashes:
            return cls._cached_hashes[path]

        hash_value = cls._calculate_hash(path)
        cls._cached_hashes[path] = hash_value
        cls._cached_hashes.sync()

        # Create a new file in a temporary directory, write the hash value, and return its path
        with tempfile.NamedTemporaryFile(suffix='.md5', delete=False, mode='w') as f:
            f.write(hash_value)
            return f.name

def file_hasher(path):
    return FileHasher.get_hash(path)
