def download_and_extract(package_url, dest):
    filename = os.path.basename(package_url)
    urllib.request.urlretrieve(package_url, dest + '/' + filename)
    with zipfile.ZipFile(dest + '/' + filename, 'r') as zip_ref:
        zip_ref.extractall(dest)
