        os.makedirs(staging_folder + '/' + product, exist_ok=True)
        os.makedirs(final_folder + '/' + product, exist_ok=True)

    for product, packages in products.items():
        for package in packages:
            download_and_extract(package, staging_folder + '/' + product)

    for product in products:
        for filename in os.listdir(staging_folder + '/' + product):
            shutil.move(staging_folder + '/' + product + '/' + filename, final_folder + '/' + product)

    for product in products:
