            for root, dirs, files in os.walk(final_folder + '/' + product):
                for file in files:
                    zip_ref.write(os.path.join(root, file), 
                                  os.path.relpath(os.path.join(root, file), final_folder))
        shutil.rmtree(final_folder + '/' + product)

