class OAuth2Client:
    def __init__(self, client_id, client_secret, auth_url, token_url, callback_url):
        self.client_id = client_id
        self.client_secret = client_secret
        self.auth_url = auth_url
        self.token_url = token_url
        self.callback_url = callback_url
        self.state = None
        self.code = None

    def start_auth_sequence(self):
        import webbrowser
        auth_params = {
           'response_type': 'code',
            'client_id': self.client_id,
           'redirect_uri': self.callback_url,
           'state': self.generate_state()
        }
        auth_url = f"{self.auth_url}?{self._encode_params(auth_params)}"
        webbrowser.open_new_tab(auth_url)

    def generate_state(self):
        return self._generate_random_string()

    def _generate_random_string(self, length=16):
        import random
        import string
        return ''.join(random.choice(string.ascii_letters + string.digits) for _ in range(length))

    def _encode_params(self, params):
        import urllib.parse
        return urllib.parse.urlencode(params)

    def get_token(self):
        assert self.code is not None, "User didn't authenticate"
        token_params = {
            'grant_type': 'authorization_code',
            'code': self.code,
           'redirect_uri': self.callback_url,
            'client_id': self.client_id,
            'client_secret': self.client_secret
        }
        response = requests.post(self.token_url, data=token_params)
        if response.status_code == 200:
            return response.json()
        else:
            return None

    def get_authenticated(self):
