        return cache
    except FileNotFoundError:
        _create_cache(cache_file)
        return {}

def _write_cache(cache, cache_file):
    root = ET.Element('cache')
    for bundle_name, bundle_cache in cache.items():
        bundle = ET.SubElement(root, 'bundle')
        bundle.set('name', bundle_name)
        for image_type, files in bundle_cache.items():
            types = ET.SubElement(bundle, 'types')
            for file in files:
                ET.SubElement(types, 'file', path=file)
            t = ET.SubElement(types, 'type')
            t.text = image_type
    tree = ET.ElementTree(root)
    tree.write(cache_file)

def _create_cache(cache_file):
    cache = {}
    for image_type in _possible_image_types():
        cache[''] = {}
        cache[''][''] = []
        for file in os.listdir('/bundle'):
            if os.path.isfile(f'/bundle/{file}') and file.endswith(image_type):
                cache[''][''].append(file)
