import requests
import re
import json

class NewRelicAlertProcessor:
    def __init__(self, webhook_url):
        self.webhook_url = webhook_url
        self.allowed_urls = re.compile(r'https://api.newrelic.com/webhooks/.*')

        self.headers = {
            'Content-Type': 'application/json'
        }

    def filter_alerts(self, alerts):
        return [alert for alert in alerts if alert['status'] == 'firing']

    def dedupe_alerts(self, alerts):
        return {k: v for i, v in enumerate(alerts) for k in [v] if i == 0 or v!= alerts[i-1]}

    def process_alerts(self, alerts):
        print("Received alerts:")
        for alert in alerts:
            print(f"Event ID: {alert['event_id']}")
            print(f"Title: {alert['event_action']}")
            print(f"Entities: {json.dumps(alert['entities'], indent=4)}")
            print("--------------------")

    def fetch_alerts(self):
        if self.allowed_urls.match(self.webhook_url):
            resp = requests.get(self.webhook_url)
            try:
                data = resp.json()
                alerts = self.filter_alerts(data["alerts"])
                alerts = self.dedupe_alerts(alerts)
                self.process_alerts(alerts)
            except json.JSONDecodeError as e:
                print(f"Failed to parse JSON: {e}")
        else:
            print("Invalid webhook URL")

