def cached_response(ttl=3600):
    def decorator(func):
        cache = {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = str(args) + str(kwargs)
            if key in cache:
                return cache[key]
            else:
                result = func(*args, **kwargs)
                cache[key] = result
                cache_expires = time.time() + ttl
                cache[key]['expires'] = cache_expires
                return result
        return wrapper
    return decorator

