import re
import requests
from concurrent.futures import ThreadPoolExecutor

def crawl(url):
    r = requests.get(url)
    html = r.text

    for link in re.findall(r'<a href="(.*?)"', html):
        if link.startswith('http'):
            yield link
        elif link.startswith('//'):
            yield f"http:{link}"
        else:
            yield f"https://{link}"

def crawl_links(url):
    links = set(crawl(url))
    with ThreadPoolExecutor() as executor:
        with requests.Session() as session:
            futures = {executor.submit(get_page, session, link): link for link in links}
            results = {future.result(): link for future, link in futures.items()}
            for new_links in map(crawl, results.values()):
                for link in new_links:
                    crawl_links(session, link)

def get_page(session, url):
    return session.get(url).text

crawl_links('http://example.com')
