import os
import argparse
import shutil
import stat
import grp
import pwd

def rename_files(path, pattern):
    for root, dirs, files in os.walk(path):
        for filename in files:
            if pattern in filename:
                parts = filename.split('.')
                new_name = '_'.join(parts[:-1]) + '.' + parts[-1]
                old_path = os.path.join(root, filename)
                new_path = os.path.join(root, new_name)
                os.rename(old_path, new_path)
                print(f"Renamed {old_path} to {new_path}")

def change_permissions(path, permissions):
    user, group, mode = permissions
    try:
        os.chown(path, pwd.getpwnam(user).pw_uid, grp.getgrnam(group).gr_gid)
        os.chmod(path, mode)
        print(f"Permissions changed for {path}")
    except Exception as e:
        print(f"Error changing permissions: {e}")

def main():
    parser = argparse.ArgumentParser(description='Rename and set permissions for files in a directory')
    parser.add_argument('path', type=str, help='path to the directory to scan')
    parser.add_argument('--rename-pattern', type=str, default='', help='rename pattern to search for')
    parser.add_argument('--rename-new', type=str, default='', help='new name pattern')
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument('--permissions', type=lambda x: x.split(','), nargs='+', help='permissions in the format user:group:mode, where user/group are names and mode is octal')
    group.add_argument('--chmod', type=lambda x: int(x, 8), help='chmod mode')
    args = parser.parse_args()

    if args.rename_pattern and args.rename_new:
        rename_files(args.path, args.rename_pattern)
        if os.path.exists(args.rename_new):
            for root, dirs, files in os.walk(args.path):
                for file in files:
                    if file.startswith(args.rename_pattern):
                        os.rename(os.path.join(root, file), os.path.join(root, args.rename_new))
    elif args.chmod:
        for root, dirs, files in os.walk(args.path):
            for file in files:
                path = os.path.join(root, file)
                if os.path.exists(path):
                    change_permissions(path, ('', '', args.chmod))
    else:
        if args.permissions:
            for root, dirs, files in os.walk(args.path):
                for file in files:
                    path = os.path.join(root, file)
                    if os.path.exists(path):
                        change_permissions(path, args.permissions)

if __name__ == "__main__":
    main()
