        self.start_time = time.time()

    def stop_benchmark(self, name):
        self.end_time = time.time()
        duration = self.end_time - self.start_time
        result = {
            'timestamp': datetime.now().isoformat(),
            'name': name,
            'duration': duration
        }
        self.results.append(result)

    def save_results(self, filename):
        with open(filename, 'w') as f:
            json.dump(self.results, f, indent=4)


class BenchmarkRunner:
    def __init__(self):
        self.logger = BenchmarkLogger()

    def run_benchmark(self, func, *args, **kwargs):
        self.logger.start_benchmark(func.__name__)
        result = func(*args, **kwargs)
        self.logger.stop_benchmark(func.__name__)
        return result

    def save_benchmark_results(self, filename):
        self.logger.save_results(filename)


