                                stats[operator] += line.count(operator)

                        for line in lines:
                            calculate_complexity(line.rstrip())

                        if lines and (len(lines) > self.max_lines or sum(stats.values()) > self.max_complexity * len(lines)):
                            print(f"Potential issue: {file} may be too long or complex (lines: {len(lines)}, complexity: {sum(stats.values())})")

    def create_report(self, filename):
        with open(filename, 'w') as f:
            for file, issues in self.issues.items():
                f.write(f"{file}:\n")
                for issue in issues:
                    f.write(f"- {issue}\n")

def create_file_in_dir(filename, dir):
    filepath = os.path.join(dir, filename)
    Path(filepath).touch()
    return filepath

def main():
    parser = argparse.ArgumentParser(description="A command-line tool that analyzes code complexity and identifies methods that are too long or complex.")
    parser.add_argument('-d', '--dirs', nargs='+', default=['.'], help='directories to analyze')
    parser.add_argument('-r', '--report-file', help='file to write the report to')
    parser.add_argument('--max-lines', type=int, help='maximum number of lines in a file')
    parser.add_argument('--max-complexity', type=int, help='maximum complexity in a file')
    args = parser.parse_args()

    analyzer = CodeAnalyzer(args.dirs, args.max_lines, args.max_complexity)
    analyzer.analyze()

    if args.report_file:
        analyzer.create_report(args.report_file)
