import re

# Connect to MongoDB database
client = MongoClient('mongodb://localhost:27017/')
db = client['cookbook']
recipes_collection = db['recipes']

# Load the template
with open('recipe_template.html') as f:
    template = Template(f.read())

def fetch_recipe(url):
    """Fetch a recipe from the given URL"""
    try:
        response = requests.get(url)
        soup = BeautifulSoup(response.text, 'html.parser')
        title = soup.find('title').text
        ingredients = [
            re.sub(r'\d+\s*(of|tsp|tbsp|cup)\s*', '', ing.text)
            for ing in soup.select('li')
            if ing.text
        ]
        instructions = [
            f"{i+1}. {step.text.strip()}"
            for i, step in enumerate(soup.select('li > p, ol > li > p'))
            if step.text
        ]
        return {
            'title': title,
            'url': url,
            'ingredients': ingredients,
            'instructions': instructions
        }
    except Exception as e:
        print(f"Failed to fetch recipe from {url}: {str(e)}")
        return None

def create_database_entry(recipe):
    """Create a new entry in the database for the given recipe"""
    recipe['id'] = recipes_collection.insert_one(recipe).inserted_id
    return recipe

def get_recipe_by_id(_id):
    """Get a recipe by its ID"""
    recipe = recipes_collection.find_one({'_id': _id})
    if recipe:
        recipe['id'] = str(recipe.pop('_id'))
        return recipe
    else:
        return None

def render_recipe(recipe):
    return template.render(recipe=recipe)

def add_recipe(url):
    """Add a new recipe to the user's cookbook"""
    recipe = fetch_recipe(url)
    if recipe:
        recipe = create_database_entry(recipe)
        return render_recipe(recipe)
    else:
        return "Failed to fetch recipe"

def get_recipe(_id):
    """Get a recipe by its ID"""
    recipe = get_recipe_by_id(_id)
    return render_recipe(recipe) if recipe else "Recipe not found"

