from jinja2 import Template, TemplateNotFound

class Album:
    def __init__(self, id, title, description, photos=None, videos=None):
        self.id = id
        self.title = title
        self.description = description
        self.photos = photos if photos else []
        self.videos = videos if videos else []

class AlbumNotFoundError(Exception):
    pass

def loader(name):
    if name == 'album.html':
        return '''
        <h1>{{ album.title }}</h1>
        <p>{{ album.description }}</p>
        <h2>Photos:</h2>
        <ul>
        {% for photo in album.photos %}
            <li>{{ photo }}</li>
        {% endfor %}
        </ul>
        <h2>Videos:</h2>
        <ul>
        {% for video in album.videos %}
            <li>{{ video }}</li>
        {% endfor %}
        </ul>
        '''
    raise TemplateNotFound(name)

def get_album(album_id):
    albums = {
        1: Album(1, 'My Album', 'A personal album'),
        2: Album(2, 'Travel Album', 'Photos from my travels', ['Paris', 'Rome', 'Tokyo'], ['Paris Trip', 'Rome Walk'])
    }
    if album_id in albums:
        return albums[album_id]
    raise AlbumNotFoundError(f'Album {album_id} not found')

def show_album(album_id):
    try:
        album = get_album(album_id)
        return Template(loader('album.html')).render(album=album)
    except TemplateNotFound:
        return 'Template not found'
    except AlbumNotFoundError as e:
        return str(e)
