def index_collection(collection):
    """Indexes a document collection.

    Args:
    collection (dict): Collection of documents with 'path' and 'documents' keys.
        'path' is the root directory of the collection.
        'documents' is a list of dictionaries containing file paths of the documents to index.

    Returns:
    None
    """
    index = {}
    for doc in collection['documents']:
        file_path = Path(doc['path'])
        if file_path.is_file():
            with open(file_path, 'r') as f:
                text = f.read().lower()  # Convert text to lowercase for case-insensitive search
        elif file_path.exists():
            # Create a temporary index for multi-file documents
            multi_docs = []
            for child in file_path.glob('*'):
                if child.is_file():
                    with open(child, 'r') as f:
                        multi_docs.append(f.read().lower())
            index[file_path] = {'docs': multi_docs}  # Store multi-documents as a dictionary
        else:
            print(f"Warning: File {file_path} does not exist.")

        for word in (text or multi_docs or [None])[0].split():
            index.setdefault(word, set()).add(doc['path'])

    # Update single file documents in the index
    for word, paths in list(index.items()):
        if isinstance(paths, dict) and 'docs' in paths and len(paths['docs']) == 1:
            doc_path = paths['docs'][0]
            if doc_path in index:
                for original_path in index.pop(doc_path):
                    index.setdefault(word, set()).add(original_path)

    index_path = Path(collection['path']) / 'index.txt'
    with open(index_path, 'w') as f:
        for word, locations in index.items():
            f.write(f'{word}:{",".join(locations)}\n')

def search_index(index_path, query):
    """Searches the index at the given path for files containing the query words.

    Args:
    index_path (Path): Path to the index file.
    query (str): Search query.

    Returns:
    list: List of paths to files containing the query words.
    """
    try:
        with open(index_path, 'r') as f:
            index = {}
            for line in f:
                word, locs = line.strip().split(':')
                index[word] = set(locs.split(','))
            query_words = query.lower().split()
            for word in query_words:
                if word in index:
                    return list(index[word])
                else:
                    query_words.remove(word)  # Ignore unknown words
            return []
    except FileNotFoundError:
        print("Error: Index file not found.")
        return []

def upload_collection(index_path, collection):
    """Uploads a new collection to the index.

    Args:
    index_path (Path): Path to the index file.
    collection (dict): Collection of documents with 'path' and 'documents' keys.
        'path' is the root directory of the collection.
        'documents' is a list of dictionaries containing file paths of the documents to index.

    Returns:
    None
    """
    if (Path(index_path).exists() and
        Path(index_path).is_file()):
        index = load_index(index_path)
        update_index(index, collection)
    else:
        create_index(collection)
        upload_index(index, collection)

