    with open(collection['path'] / 'index.txt', 'w') as f:
        for word, locations in new_index.items():
            f.write(f'{word}:{",".join(locations)}\n')
    return new_index

def load_index(path):
    index = {}
    try:
        with open(path, 'r') as f:
            for line in f:
                word, locs = line.strip().split(':')
                if ':' in locs:
                    for doc_path, sub_locs in (locs + '').split(':').items():
                        locs = doc_path.split(',') + locs.split(',')
                index[word] = {doc_path for doc_path in locs.split(',')}
    except FileNotFoundError:
        return {'': set()}
    return index

def get_words(file_path, collection):
    try:
