import os
import pefile
import imaging

def unpack_iso(iso_path):
    # Check the file type and create a filesystem
    if iso_path.lower().endswith('.iso'):
        filesystem = imaging.open(iso_path)
    elif iso_path.lower().endswith('.wim'):
        wim = pefile.WIMParser().read(iso_path)
        filesystem = wim.get_image_files()
    else:
        raise ValueError("Unsupported file type")

    # Determine the target directory
    base_name = os.path.basename(iso_path)
    target_dir = os.path.join(os.getcwd(), base_name[:-4])  # Remove the file extension

    # Unpack the filesystem into the target directory
    if iso_path.lower().endswith('.iso'):
        for tarinfo in filesystem:
            filesystem.extract(tarinfo.path, path=target_dir)
    elif iso_path.lower().endswith('.wim'):
        for filename in filesystem.values():
            with open(os.path.join(target_dir, filename.name), 'wb') as f:
                f.write(filename.contents)
    else:
        raise ValueError("Unsupported file type")

    # Clean up
    try:
        filesystem.close()
    except AttributeError:
        pass
    if iso_path.lower().endswith('.wim'):
        del wim
    return target_dir
