from bs4 import BeautifulSoup
import requests
from urllib.parse import urljoin, urlparse
from collections import deque

def crawl(url, max_depth=2):
    urls_to_crawl = deque([(url, 0)])
    crawled_urls = set()

    while urls_to_crawl:
        current_url, depth = urls_to_crawl.popleft()

        if current_url in crawled_urls:
            continue

        crawled_urls.add(current_url)

        try:
            r = requests.get(current_url)
            r.raise_for_status()
        except requests.exceptions.RequestException as e:
            print(f"Error crawling {current_url}: {e}")
            continue

        soup = BeautifulSoup(r.text, 'html.parser')

        for link in soup.find_all('a'):
            link_href = link.get('href')
            if link_href and link_href.startswith('/'):
                link_href = urljoin(current_url, link_href)
            elif not link_href.startswith('http'):
                continue

            if urlparse(link_href).netloc == urlparse(url).netloc:
                urls_to_crawl.append((link_href, depth + 1))

        depth += 1
        if depth > max_depth:
            continue

        for link in soup.find_all('a'):
            if link.get('noindex'):
                print(f"Skipping {link.get('href')} due to 'noindex' directive")
                soup.find_all('a')[link.get('noindex_idx')].decompose()
                link.decompose()

        for noindex in soup.find_all('meta', attrs={'name': 'robots', 'content': 'noindex'}):
            soup.find_all('meta', attrs={'name': 'robots', 'content': noindex.get('content')}).decompose()
            noindex.decompose()

        for link in soup.find_all('a'):
            urls_to_crawl.append((link.get('href'), depth + 1))

    return crawled_urls
