import shutil
import tarfile
import os
from datetime import datetime

class BackupUtility:
    def __init__(self, backup_dir, archive_name):
        self.backup_dir = backup_dir
        self.archive_name = archive_name

    def _create_archive(self):
        with tarfile.open(self.archive_name, 'w:gz') as tar:
            for root, dirs, files in os.walk(self.backup_dir):
                for file in files:
                    file_path = os.path.join(root, file)
                    tar.add(file_path, arcname=os.path.relpath(file_path, self.backup_dir))

    def _delete_old_backups(self):
        backup_path = os.path.join(self.backup_dir, self.archive_name)
        current_timestamp = int(datetime.now().timestamp())
        for filename in os.listdir(self.backup_dir):
            if filename.startswith(self.archive_name.split('.')[0]) and 'gz' in filename:
                timestamp = int(filename.split('.')[0].split('_')[1])
                if current_timestamp - timestamp > 24 * 60 * 60:
                    os.remove(os.path.join(self.backup_dir, filename))

    def run(self):
        self._create_archive()
        self._delete_old_backups()


if __name__ == "__main__":
    backup_dir = '/path/to/your/directory'
    archive_name = 'backup_files.tar.gz'
    if not os.path.exists(backup_dir):
        os.makedirs(backup_dir)

    backup = BackupUtility(backup_dir, archive_name)
    backup.run()
```

