import ast
import inspect
import re
import textwrap

def load_ast(node):
    try:
        node = ast.parse(open(node).read())
    except FileNotFoundError:
        node = ast.parse(inspect.getsource(file).encode('utf-8'))
    return node

def extract_uncovered(node):
    uncovered = []
    uncovered_dict = {}
    for child_class in ast.walk(node):
        if isinstance(child_class, ast.ClassDef):
            class_name = child_class.name
            uncovered_class_lines = []
            for line in inspect.getsourcelines(child_class)[1:]:
                line = re.sub(r'\s+','', line).strip()
                if not re.search(r'    @\w+', line):
                    uncovered_class_lines.append((line, True))
                else:
                    uncovered_class_lines.append((line, False))
            uncovered_dict[class_name] = uncovered_class_lines
    return uncovered_dict

def generate_annotation_lines(lines):
    lines = [(re.sub(r'\s+','', line).strip(), new) for line, new in lines]
    return ['''# NEW TEST REQUIRED '''] + lines

def save_annotations(annotation_lines, filename):
    with open(f'{filename}.annotated', 'w') as f:
        for line in annotation_lines:
            f.write(textwrap.fill(line) + '\n')

def find_uncovered_functions(file, uncovered_dict):
    for class_name, lines in uncovered_dict.items():
        covered_functions = []
        uncovered_functions = []
        for line, is_new in lines:
            if is_new:
                line = re.sub(r'\w+', '', line)
                if ':' in line:
                    start, end = line.split(':', 1)
                    line = re.sub(r'[^:]', '', end).strip()
                    end = int(re.search(r'(\d+)', end).group())
                    if end:
                        uncovered_functions.append((textwrap.fill(f'{class_name}.{line}', 80), end))
            elif line.strip():
                covered_functions.append(line)
        print(f'Class {class_name}:')
        for func, line in uncovered_functions:
            print(f'  - {func} (line {line})')

def main():
    node = load_ast('example.py')
    uncovered = extract_uncovered(node)
    if uncovered:
        for class_name, lines in uncovered.items():
            print(f'{class_name} has uncovered lines:')
            for line, is_new in lines:
                print(f'  - {line} ({"new" if is_new else "covered"})')
            save_annotations(lines, class_name)
        for class_name, lines in uncovered.items():
            find_uncovered_functions(class_name, uncovered)
    else:
        print('No uncovered lines found.')

if __name__ == '__main__':
    main()
