import tarfile
import os
import boto3
from concurrent.futures import ThreadPoolExecutor

class S3ZipExtractor:
    def __init__(self, bucket_name, object_key):
        self.bucket_name = bucket_name
        self.object_key = object_key
        self.s3 = boto3.client('s3')

    def extract_files(self):
        obj = self.s3.get_object(Bucket=self.bucket_name, Key=self.object_key)
        filename = os.path.join(os.path.dirname(__file__), f"{self.object_key}")
        with open(filename, 'wb') as file:
            file.write(obj['Body'].read())

        return self._extract_tar(filename)

    def _extract_tar(self, filename):
        try:
            with tarfile.open(filename) as tar:
                for member in tar.getmembers():
                    if member.isfile():
                        filename = member.name
                        tar.extract(member, path=os.path.join(os.path.dirname(__file__), f"{self.object_key}"))

        except FileNotFoundError:
            return f"Error: File not found."

        finally:
            os.remove(filename)
            return f"Files extracted successfully from {self.object_key}"

class LocalZipExtractor:
    def __init__(self, filename):
        self.filename = filename

    def extract_files(self):
        return self._extract_tar(self.filename)

    def _extract_tar(self, filename):
        try:
            with tarfile.open(filename) as tar:
                for member in tar.getmembers():
                    if member.isfile():
                        filename = member.name
                        tar.extract(member, path=os.path.dirname(filename))

        except tarfile.TarError:
            return f"Error: Extraction unsuccessful."

        return f"Files extracted successfully from {self.filename}"

def extract_files(filename_or_bucket_object_key, bucket_name=None):
    if bucket_name:
        return S3ZipExtractor(bucket_name, filename_or_bucket_object_key).extract_files()
    else:
        return LocalZipExtractor(filename_or_bucket_object_key).extract_files()

