        response.raise_for_status()
        return response.json()['lyrics']
    except requests.exceptions.RequestException as e:
        print(f"Failed to fetch lyrics for '{song}': {e}")
        return None

def write_lyrics_to_file(lyrics: str, song: str):
    permissions = read_permissions()
    if permissions.get(song, False):
        print(f'Wrote lyrics to {song}.txt')
        filename = os.path.join(lyrics_dir, song) + '.txt'
        filename_absolute = pathlib.Path(filename).absolute()
        if not filename_absolute.parent.exists():
            os.makedirs(filename_absolute.parent)
        write_lyrics(filename, lyrics)
    else:
        print(f'Cannot write lyrics for {song}. Permission denied.')

def write_lyrics(filename: str, lyrics: str):
    with open(filename, 'w') as f:
        f.write(lyrics)

def add_permission(song: str):
