import zipfile
import tarfile
import rarfile
import py7zr

class CompressedFileExtractor:
    def __init__(self, file_path):
        self.file_path = file_path
        self.extracted_files = {}

    def extract_zip(self):
        try:
            with zipfile.ZipFile(self.file_path, 'r') as zip_ref:
                self.extracted_files = {f.filename: f for f in zip_ref.filelist}
                zip_ref.extractall()
        except zipfile.BadZipFile:
            print(f"Error: {self.file_path} is not a valid zip file.")

    def extract_tar(self):
        try:
            with tarfile.TarFile(self.file_path, 'r') as tar_ref:
                self.extracted_files = {f.name: f for f in tar_ref.getmembers()}
                tar_ref.extractall()
        except tarfile.TarError:
            print(f"Error: {self.file_path} is not a valid tar file.")

    def extract_rar(self):
        try:
            with rarfile.RarFile(self.file_path, 'r') as rar_ref:
                self.extracted_files = {f.filename: f for f in rar_ref.namelist()}
                rar_ref.extractall()
        except rarfile.BadRarFile:
            print(f"Error: {self.file_path} is not a valid rar file.")

    def extract_7zip(self):
        try:
            with py7zr.SevenZipFile(self.file_path, mode='r') as sevenzip_ref:
                self.extracted_files = {f.filename: f for f in sevenzip_ref.getnames()}
                sevenzip_ref.extractall()
        except py7zr.SevenZipExtractError:
            print(f"Error: {self.file_path} is not a valid 7zip file.")

def extract_compressed_file(file_path):
    extractor = CompressedFileExtractor(file_path)
    file_name, file_extension = file_path.split('.')
    extractor.extract_zip() if file_extension == 'zip' else \
    extractor.extract_tar() if file_extension == 'tar' else \
    extractor.extract_rar() if file_extension == 'rar' else \
    extractor.extract_7zip() if file_extension == '7z' else \
    print(f"Error: {file_path} is not a valid compressed file.")
    return extractor.extracted_files
