import os
import mimetypes
import hashlib
from datetime import datetime, timedelta

class WebCache:
    def __init__(self, cache_dir, max_age=3600):
        self.cache_dir = cache_dir
        self.max_age = timedelta(seconds=max_age)
        os.makedirs(self.cache_dir, exist_ok=True)

    def get(self, url):
        filename = self._calculate_filename(url)
        filepath = os.path.join(self.cache_dir, filename)
        if os.path.isfile(filepath):
            timestamp = os.path.getmtime(filepath)
            age = datetime.now() - datetime.fromtimestamp(timestamp)
            if age < self.max_age:
                with open(filepath, 'rb') as f:
                    return f.read(), mimetypes.guess_type(url)[0]
        return None, None

    def set(self, url, data, headers):
        filename = self._calculate_filename(url)
        filepath = os.path.join(self.cache_dir, filename)
        with open(filepath, 'wb') as f:
            f.write(data)
        self._update_metadata(filepath, headers)

    def _calculate_filename(self, url):
        return hashlib.md5(url.encode()).hexdigest()

    def _update_metadata(self, filepath, headers):
        with open(filepath + '.meta', 'w') as f:
            f.write(str(headers))


class WebCacheServer:
    def __init__(self, cache):
        self.cache = cache

    def get(self, url):
        data, content_type = self.cache.get(url)
        if data is not None:
            return {
               'status_code': 200,
                'headers': {'Content-Type': content_type},
                'body': data
            }
        else:
            return {
               'status_code': 404,
                'headers': {},
                'body': b''
            }

    def set(self, url, data, headers):
        self.cache.set(url, data, headers)


