        raise ValueError('Invalid username')

    avatar_path = get_avatar_path(username)
    ensure_directory_exists(avatar_path)
    with open(avatar_path, 'wb') as f:
        f.write(avatar)
    set_avatar_permissions(avatar_path)

def restrict_upload_file(func):
    @wraps(func)
    def decorator(filename, avatar_data, username):
        if not validate_username(username):
            raise ValueError('Invalid username')
        if not isinstance(avatar_data, (bytes, bytearray)):
            raise ValueError('Avatar must be a bytes object')
        if not filename.lower().endswith(('.jpg', '.jpeg')):
            raise ValueError('Unsupported file format')
        return func(filename, avatar_data, username)
    return decorator

