import zipfile
from pathlib import Path

class StaticSiteGenerator:
    def __init__(self, input_dir, output_file):
        self.input_dir = input_dir
        self.output_file = output_file
        self.tarball_type = "tar.gz"

    def create_tarball(self):
        if not os.path.exists(self.input_dir):
            raise FileNotFoundError(f"The directory '{self.input_dir}' does not exist.")

        if self.tarball_type == "tar.gz":
            with tarfile.open(self.output_file, "w:gz") as tar:
                for dirpath, _, filenames in os.walk(self.input_dir):
                    for filename in filenames:
                        filepath = str(Path(dirpath) / filename)
                        rel_path = os.path.relpath(filepath, self.input_dir)
                        # add data to tar
                        tar.add(filepath, rel_path)
        elif self.tarball_type == "zip":
            with zipfile.ZipFile(self.output_file, 'w') as zip_file:
                for dirpath, _, filenames in os.walk(self.input_dir):
                    for filename in filenames:
                        filepath = str(Path(dirpath) / filename)
                        rel_path = os.path.relpath(filepath, self.input_dir)
                        zip_file.write(filepath, rel_path)

if __name__ == "__main__":
    generator = StaticSiteGenerator("input_directory", "output.tar.gz")
    generator.create_tarball()
