from queue import Queue
from urllib.parse import urljoin, urlparse

def is_valid_url(url):
    try:
        result = urlparse(url)
        return all([result.scheme, result.netloc])
    except ValueError:
        return False

def crawl(url, queue, visited, graph):
    if is_valid_url(url):
        if url not in visited:
            queue.put(url)
            visited.add(url)
            resp = requests.get(url)
            soup = BeautifulSoup(resp.text, 'html.parser')
            links = soup.findAll('a')

            for link in links:
                href = link.get('href')
                if href:
                    absolute_url = urljoin(url, href)
                    crawl(absolute_url, queue, visited, graph)

    else:
        graph[url] = []

def build_graph():
    sitemap = defaultdict(list)
    queue = Queue()
    visited = set()

    queue.put('http://example.com')
    visited.add('http://example.com')

    while not queue.empty():
        url = queue.get()
        crawl(url, queue, visited, sitemap)

    return sitemap

def visualize_graph(graph):
    from heapq import nlargest
    from collections import Counter

    counter = Counter()
    for urls in graph.values():
        counter.update(urls)

    top_references = nlargest(10, counter.items(), key=lambda x: x[1])

    for i, (url, count) in enumerate(top_references):
        print(f'{i+1}. {url}: {count}')

