import os
import shutil
from pathlib import Path
import requests
import json

CACHE_DIR = Path('/tmp/cache')
CACHE_METADATA = CACHE_DIR /'metadata.json'

def get_asset(asset_id, url):
    try:
        response = requests.get(url)
        return response.content
    except requests.exceptions.RequestException as err:
        print(f"Error downloading asset {asset_id}: {err}")
        return None

def cache_asset(asset_id, asset):
    cache_path = CACHE_DIR / asset_id
    os.makedirs(CACHE_DIR, exist_ok=True)
    with open(cache_path, 'wb') as f:
        f.write(asset)
    return cache_path

def read_cache_metadata():
    try:
        with open(CACHE_METADATA, 'r') as f:
            return json.load(f)
    except (FileNotFoundError, json.JSONDecodeError):
        return {}

def write_cache_metadata(metadata):
    with open(CACHE_METADATA, 'w') as f:
        json.dump(metadata, f)

def clean_cache():
    cache_paths = list(CACHE_DIR.glob('*'))
    for path in cache_paths:
        shutil.rmtree(str(path), ignore_errors=True)
    try:
        shutil.rmtree(CACHE_DIR)
    except OSError as e:
        print(f"Error cleaning cache: {e}")

def cache_asset_on_demand(asset_id):
    metadata = read_cache_metadata()
    if asset_id in metadata and os.path.exists(CACHE_DIR / asset_id):
        return CACHE_DIR / asset_id

    asset = get_asset(asset_id, metadata.get(asset_id))
    if asset:
        cache_path = cache_asset(asset_id, asset)
        write_cache_metadata({**metadata, asset_id: cache_path})
        return cache_path

if __name__ == '__main__':
    clean_cache()
