import os
import tarfile
import zipfile
import lzma
import rarfile

def extract_data_from_compressed_file(file_path):
    """
    Extracts data from a compressed file.

    Args:
        file_path (str): The path to the compressed file.

    Returns:
        str: The path to the extracted file or None if the extraction was unsuccessful.
    """
    if file_path.endswith('.tar.gz'):
        with tarfile.open(file_path, 'r:gz') as tar:
            return tar.extractall()
    elif file_path.endswith('.tar'):
        with tarfile.open(file_path, 'r') as tar:
            return tar.extractall()
    elif file_path.endswith('.xz'):
        with lzma.open(file_path, 'rb') as file:
            return file_path + '.decompressed'
    elif file_path.endswith('.zip'):
        with zipfile.ZipFile(file_path, 'r') as zip_ref:
            return zip_ref.extractall()
    elif file_path.endswith('.rar'):
        with rarfile.RarFile(file_path, 'r') as rar:
            return rar.extractall()
    else:
        return None

def main():
    file_path = 'path_to_your_compressed_file.tar.gz'
    if extract_data_from_compressed_file(file_path):
        print("Data extracted successfully")
    else:
        print("Failed to extract data")

if __name__ == "__main__":
    main()
