    def _scan_directory_recursive(self, directory, stack):
        try:
            files = os.listdir(directory)
            for f in files:
                file_path = os.path.join(directory, f)
                if os.path.isdir(file_path):
                    self.scan_directory(file_path, stack + [directory])
                else:
                    with open(file_path, 'rb') as file:
                        md5 = hashlib.md5(file.read()).hexdigest()
                        if md5 not in self.tarball_contents:
                            self.tarball_contents[md5] = file_path
                    stack.append(file_path)
        except (OSError, IOError):
            print(f"Unable to scan directory: {directory}")
        return stack

    def analyze(self):
        try:
            files = self.extract_tarball()
            self._scan_directory_recursive('/', files)
