import tarfile
from typing import Dict, List
from pathlib import Path
import os
import subprocess

class RepositoryCheckoutTool:
    def __init__(self, repo_path: str, dest_path: str):
        self.repo_path = repo_path
        self.dest_path = dest_path

    def extract_archive(self, archive_path: str):
        with tarfile.open(archive_path, 'r:gz') as tar_ref:
            tar_ref.extractall(self.dest_path)

    def list_archives(self) -> List[str]:
        return [file for file in os.listdir(self.repo_path) if file.endswith('.tar.gz')]

    def checkout_repository(self):
        archives = self.list_archives()
        for archive in archives:
            self.extract_archive(os.path.join(self.repo_path, archive))
            print(f'Checkout success: {archive}')

class Git:
    def __init__(self):
        self.last_commit_hash = None

    def get_last_commit_hash(self):
        try:
            return subprocess.check_output(['git','rev-parse', '--short', 'HEAD']).decode('utf-8').strip()
        except FileNotFoundError:
            return None

def create_archive(repodir: str, repo_name: str):
    git = Git()
    last_commit_hash = git.get_last_commit_hash()

    if last_commit_hash:
        archive_path = f'{repo_name}_v{last_commit_hash}.tar.gz'
        with tarfile.open(archive_path, 'w:gz') as tar_ref:
            for file in os.listdir(repodir):
                tar_ref.add(os.path.join(repodir, file))
        return archive_path
    else:
        return None

def checkout_and_create_archive(repodir: str, repo_name: str, dest_path: str):
    archive_path = create_archive(repodir, repo_name)
    if archive_path:
        checkout_tool = RepositoryCheckoutTool(dest_path, dest_path)
        checkout_tool.checkout_repository()

