def extract_compressed_file(file_path):
    """
    Exrates compressed file with supported formats (zip, tar, rar, 7z)

    Args:
        file_path (str): Path to the compressed file
    """
    file_name, file_ext = os.path.splitext(file_path)

    if file_ext.lower() == '.zip':
        with ZipFile(file_path) as zip_file:
            zip_file.extractall()
            return zip_file.namelist()
    elif file_ext.lower() in ['.tar', '.tgz', '.tar.gz']:
        with tarfile.open(file_path) as tar_file:
            tar_file.extractall()
            return tar_file.getnames()
    elif file_ext.lower() == '.rar':
        with rarfile.RarFile(file_path) as rar_file:
            rar_file.extractall()
            return rar_file.namelist()
    elif file_ext.lower() == '.7z':
