import logging

class PackageInstaller:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    def extract_tarball(self, filename, destination):
        try:
            with tarfile.open(filename, 'r:gz') as tar:
                tar.extractall(destination)
                self.logger.info(f"Extractor finished extracting {filename} to {destination}")
        except tarfile.TarError as e:
            self.logger.error(f"Error extracting file {filename}: {e}")
            raise

    def clean_destination(self, destination):
        try:
            if os.path.exists(destination):
                if os.path.isdir(destination):
                    shutil.rmtree(destination)
                    self.logger.info(f"Cleaned up {destination}")
                else:
                    os.remove(destination)
                    self.logger.info(f"Removed {destination}")
            else:
                self.logger.warning(f"{destination} does not exist")
        except Exception as e:
            self.logger.error(f"Error cleaning destination: {e}")

    def install_packages(self, filename, destination):
        if not filename.endswith('.tar.gz'):
            self.logger.error("File is not a tarball")
            return
        destination = os.path.join(destination, os.path.splitext(os.path.basename(filename))[0])
        self.extract_tarball(filename, destination)
        self.clean_destination(destination)


