from typing import List, Dict, Tuple
from heapq import heappop, heappush
import requests

class Graph:
    def __init__(self):
        self.nodes = {}
        self.edges = {}

    def add_node(self, node_id: str):
        if node_id not in self.nodes:
            self.nodes[node_id] = Node(node_id)
            self.edges[node_id] = {}

    def add_edge(self, node1: str, node2: str, weight: float, road_name: str):
        self(edges[node1])[node2] = {'weight': weight, 'road_name': road_name}
        self(edges[node2])[node1] = {'weight': weight, 'road_name': road_name}

class Node:
    def __init__(self, node_id: str):
        self.id = node_id
        self.visited = False

class Directions:
    def __init__(self, graph: Graph):
        self.graph = graph

    def dijkstra(self, start_node: str, end_node: str) -> List[Tuple[str, float]]:
        unvisited = [(0, start_node)]
        shortest_distances = {node: float('inf') for node in self.graph.nodes}
        previous_nodes = {node: None for node in self.graph.nodes}

        while unvisited:
            current_distance, current_node = heappop(unvisited)

            if current_node == end_node:
                break

            if shortest_distances[current_node] < current_distance:
                continue

            for neighbor, edge in self.graph.edges[current_node].items():
                distance = current_distance + edge['weight']

                if distance < shortest_distances[neighbor]:
                    shortest_distances[neighbor] = distance
                    previous_nodes[neighbor] = current_node
                    heappush(unvisited, (distance, neighbor))

        path = []
        current_node = end_node
        while current_node is not None:
            path.append(current_node)
            current_node = previous_nodes[current_node]

        return list(reversed(path)), shortest_distances[end_node]

class Traffic:
    def __init__(self):
        self.traffic_data = {
            'road_name': {
                'traffic_condition': {
                    'light': 1,
                   'moderate': 0.75,
                    'heavy': 0.5
                }
            }
        }

    def get_traffic(self, road_name: str) -> float:
        return self.traffic_data['road_name'][road_name]['traffic_condition']

class Search:
    def __init__(self, graph: Graph, directions: Directions, traffic: Traffic):
        self.graph = graph
        self.directions = directions
        self.traffic = traffic

    def search_destination(self, start_location: str, end_location: str):
        self.graph.add_node(start_location)
        self.graph.add_node(end_location)
        self.directions.graph.add_edge(start_location, end_location, 1.0, "(direct route)")

        path, total_time = self.directions.dijkstra(start_location, end_location)
        traffic_time = self.calculate_traffic_time(path)
        return self.display_directions(start_location, end_location, path, total_time, traffic_time)

    def calculate_traffic_time(self, path: List[str]) -> float:
        traffic_time = 0.0
        for i in range(len(path) - 1):
            road_name = self.get_road_name(self.graph.graph, path[i], path[i + 1])
            traffic_condition = self.traffic.get_traffic(road_name)
            traffic_time += self.graph.edges[path[i]][path[i + 1]]['weight'] * traffic_condition

        return traffic_time

    def get_road_name(self, graph: Graph, node1: str, node2: str) -> str:
        weights = graph.edges[node1]
