            return False

    @staticmethod
    def csv_to_json(csv_file: str, json_file: str) -> bool:
        import csv
        import json
        try:
            with open(csv_file, 'r') as csv_file_open:
                csv_reader = csv.DictReader(csv_file_open)
                data = [row for row in csv_reader]
            with open(json_file, 'w') as json_file_open:
                json.dump(data, json_file_open, indent=4)
            return True
        except Exception as e:
            print(f"Error occurred while converting {csv_file} to {json_file}: {str(e)}")
            return False

    @staticmethod
    def json_to_csv(json_file: str, csv_file: str) -> bool:
        import json
        try:
            with open(json_file, 'r') as json_file_open:
                data = json.load(json_file_open)
            with open(csv_file, 'w', newline='') as csv_file_open:
                fieldnames = data[0].keys() if data else []
                csv_writer = csv.DictWriter(csv_file_open, fieldnames=fieldnames)
                csv_writer.writeheader()
                csv_writer.writerows(data)
            return True
        except Exception as e:
            print(f"Error occurred while converting {json_file} to {csv_file}: {str(e)}")
