from flask import Flask, request, render_template_string

app = Flask(__name__)

@app.route('/', methods=['POST'])
def index():
    try:
        file_path = request.form['file']
        with open(file_path, 'r') as f:
            python_code = f.read()
        tree = ast.parse(python_code)
    except FileNotFoundError:
        return render_template_string('<p>Error: File not found</p>')
    except SyntaxError as e:
        return f'<p>Error: {e}</p>'
    else:
        try:
            type_annotations = add_type_annotations(tree)
            typed_code = astunparse.unparse(type_annotations)
            return render_template_string(f'<p>Typed code:</p><pre>{typed_code}</pre>')
        except Exception as e:
            return f'<p>Error: {e}</p>'

def add_type_annotations(tree):
    def add_type_annotation(node):
        if isinstance(node, ast.FunctionDef):
            for arg in node.args.args:
                arg.annotation = ast.NameConstant(value=str(arg.arg) + ': any')
            for arg in node.args.kwonlyargs:
                arg.annotation = ast.NameConstant(value=str(arg.arg) + ': any')
            for arg in node.args.args:
                for child in ast.walk(node):
                    if isinstance(child, ast.Call):
                        if isinstance(child.func, ast.Name) and child.func.id == arg.arg:
                            child.args[0].annotation = ast.NameConstant(value='None')
            return node
        elif isinstance(node, ast.ClassDef):
            for method in node.body:
                if isinstance(method, ast.FunctionDef):
                    for arg in method.args.args:
                        arg.annotation = ast.NameConstant(value=str(arg.arg) + ': any')
                    for arg in method.args.kwonlyargs:
                        arg.annotation = ast.NameConstant(value=str(arg.arg) + ': any')
                    for arg in method.args.args:
                        for child in ast.walk(method):
                            if isinstance(child, ast.Call):
                                if isinstance(child.func, ast.Name) and child.func.id == arg.arg:
                                    child.args[0].annotation = ast.NameConstant(value='None')
            return node
        else:
            return node

    return add_types_from_nodes([tree])

def add_types_from_nodes(nodes):
    for node in nodes:
        if isinstance(node, ast.FunctionDef):
            yield node
        elif isinstance(node, ast.ClassDef):
            for child in ast.walk(node):
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    yield child
        else:
            for child in ast.walk(node):
                if isinstance(child, (ast.FunctionDef, ast.AsyncFunctionDef)):
                    yield child

