    return image

def process_image(file):
    """Resizes and saves the uploaded image."""
    filename = secure_filename(file.filename)
    original_image_path = os.path.join(app.config['UPLOAD_FOLDER'], filename)
    image = Image.open(original_image_path)

    # Create thumbnail
    thumb_size = (512, None)
    thumb_path = os.path.join(app.config['UPLOAD_FOLDER'], 'thumbnail_' + filename)
    thumbnail = resize_image(image, thumb_size)
    thumbnail.save(thumb_path)

    return original_image_path, thumb_path

@app.route('/upload', methods=['POST'])
def upload_file():
    """Handles file upload."""
    file = request.files['file']
    if file and allowed_file(file.filename):
        original_image_path, thumb_path = process_image(file)
        return {'original_image_path': original_image_path, 'thumbnail_path': thumb_path}
    return {'error': 'Invalid file or empty file'}, 400

def allowed_file(filename):
    """Checks if the filename has a valid image extension."""
    allowed_extensions = set(['jpg', 'png', 'gif', 'bmp'])
