def get_permissions():
    # Define available permissions
    permissions = {
        'x': stat.S_IXOTH | stat.S_IXGRP | stat.S_IXUSR,
        'r': stat.S_IROTH | stat.S_IRGRP | stat.S_IROTH,
        'w': stat.S_IWOTH | stat.S_IWGRP | stat.S_WUSR,
        'r-x': stat.S_IXOTH | stat.S_IRGRP | stat.S_IROTH | stat.S_IRUSR | stat.S_IXUSR,
        'rw-': stat.S_IWOTH | stat.S_IWGRP | stat.S_WUSR | stat.S_IRUSR,
        'r-xw': stat.S_IXOTH | stat.S_IWOTH | stat.S_IWGRP | stat.S_WUSR | stat.S_IRUSR | stat.S_IXUSR,
        'rwx': stat.S_IXOTH | stat.S_IWOTH | stat.S_IWGRP | stat.S_WUSR | stat.S_IRUSR | stat.S_IXUSR,
        'rw-r--': stat.S_IRUSR | stat.S_IRGRP | stat.S_IROTH,
        'r-xr-x': stat.S_IXOTH | stat.S_IRGRP | stat.S_IROTH | stat.S_IRUSR | stat.S_IXUSR,
        'rw-r-x': stat.S_IWUSR | stat.S_IRUSR | stat.S_IRGRP | stat.S_IROTH | stat.S_IXUSR,
        'r-xrw-': stat.S_IWUSR | stat.S_IWGRP | stat.S_IWOTH | stat.S_IRGRP | stat.S_IROTH | stat.S_IXUSR,
        'r-xr-xw': stat.S_IWUSR | stat.S_IRUSR | stat.S_IRGRP | stat.S_IROTH | stat.S_IXUSR | stat.S_IXOTH,
        'r-xrwx': stat.S_IWUSR | stat.S_IWGRP | stat.S_IWOTH | stat.S_IRGRP | stat.S_IROTH | stat.S_IXUSR | stat.S_IXOTH
    }

    return {v: k for k, v in permissions.items()}

def apply_permissions(path, permission):
    # Define available file modes
    modes = get_permissions()
    try:
        mode = modes[permission]
        for root, dirs, files in os.walk(path):
            for filename in files:
                item_path = os.path.join(root, filename)
                try:
                    attr = os.stat(item_path).st_mode
                    os.chmod(item_path, attr | mode)
                except OSError:
                    print(f"Error setting permissions for {item_path}")
    except KeyError:
        print(f"Invalid permission: {permission}")

def get_new_filename(old_name, pattern, replacement):
    return old_name.replace(pattern, replacement)

def rename_files(path, old_pattern, new_pattern):
    for root, dirs, files in os.walk(path):
        for filename in files:
            if old_pattern in filename:
                new_name = get_new_filename(filename, old_pattern, new_pattern)
                new_path = os.path.join(root, new_name)
                old_path = os.path.join(root, filename)
                try:
                    os.rename(old_path, new_path)
                    print(f"Renamed {old_path} to {new_path}")
                except OSError as e:
                    print(f"Error renaming {old_path}: {e}")

def main():
    parser = argparse.ArgumentParser(description='Bulk rename files and apply permissions')
    parser.add_argument('-p', '--path', help='Path to the directory to process', required=True)
    parser.add_argument('-r', '--rename', help='Old pattern to find in filenames, new pattern to replace it', action='append')
    parser.add_argument('-a', '--apply', help='Permission to apply to renamed files', choices=list(get_permissions().keys()))
    args = parser.parse_args()

    for rename in args.rename:
        rename_parts = rename.split(',')
        old_pattern = rename_parts[0]
        new_pattern = rename_parts[1]

        rename_files(args.path, old_pattern, new_pattern)

    if args.apply:
        apply_permissions(args.path, args.apply)

if __name__ == "__main__":
