import requests
from bs4 import BeautifulSoup
from urllib.parse import urljoin
from collections import defaultdict

def generate_sitemap(urls):
    sitemap = defaultdict(list)

    for url in urls:
        response = requests.get(url)
        bs = BeautifulSoup(response.text, 'html.parser')
        for link in bs.find_all('a'):
            href = link.get('href')
            if href and href.startswith('/'):
                href = urljoin(url, href)
            sitemap[url].append(href.strip('/'))

    return sitemap

def sort_sitemap(sitemap):
    def get_depth(url):
        if not url.startswith('/'):
            raise ValueError('Invalid URL')
        depth = 0
        for part in url.split('/'):
            if part and not part.isdigit():
                depth += 1
        return depth

    sorted_sitemap = {}
    for url, subpage in sitemap.items():
        sorted_subpage = sorted(subpage, key=get_depth)
        sorted_sitemap[url] = sorted_subpage

    return sorted_sitemap

def generate_html_sitemap(sitemap):
    html = '<html><body><h1>Sitemap</h1><ul>'
    for url, subpage in sitemap.items():
        html += f'<h2>{url}</h2><ul>'
        for subpage in subpage:
            html += f'<li><a href="{subpage}">{subpage}</a></li>'
        html += '</ul>'
    html += '</ul></body></html>'
    return html

def main(urls):
    sitemap = generate_sitemap(urls)
    sorted_sitemap = sort_sitemap(sitemap)
    html = generate_html_sitemap(sorted_sitemap)
    return html

# Example usage:
urls = ['https://www.example.com', 'https://www.example.com/subpage']
print(main(urls))
