import os
import json
from mako.template import Template

def update_variables_in_template(context, template_string):
    """Updates variables in a template string."""
    import re
    pattern = r'\$\{([^}]*)\}'
    def replacement(match):
        return str(context.get(match.group(1), ''))
    return re.sub(pattern, replacement, template_string)

def render_mako_strings(template_strings, output_dir, context):
    for template_string in template_strings:
        filename = template_string.split()[0].replace('{{', '').replace('}}', '') + '.html'
        updated_template_string = update_variables_in_template(context, template_string)
        template = Template(updated_template_string)
        rendered = template.render()

        output_path = os.path.join(output_dir, filename)
        with open(output_path, 'w') as f:
            f.write(rendered)

template_strings = [
    '<h1>${title}</h1>',
    '<p>${content}</p>'
]
render_mako_strings(template_strings, 'public_html', {'title': 'Home', 'content': 'Welcome!'})
if __name__ == "__main__":
    data = {'input': {'templates': [
        {'type': 'example_template1', 'content': '<h1>{title}</h1>'},
        {'type': 'example_template2', 'content': '<p>{content}</p>'}
    ]}, 'output_dir': 'public_html', 'context': {'title': 'Home', 'content': 'Welcome!'}}
    json.dump(data, open('input.json', 'w'))
    input_data = json.load(open('input.json'))
    render_mako_strings([update_variables_in_template(input_data['context'], template['content']) for template in input_data['templates']], input_data['output_dir'], input_data['context'])
    os.remove('input.json')
