from whoosh.index import create_in, schema, store
from whoosh.fields import TEXT, ID
from os import path
from os import _exists

app = Flask(__name__)

class Indexer:
    def __init__(self):
        self.ix = None
        self.schema = schema.StandardSchema(fieldnames={
            'id': ID(stored=True),
            'title': TEXT,
            'content': TEXT
        })

    def create_index(self):
        path_ = 'index.db'
        if not path.exists(path_):
            store = store.InmemoryStore()
            ix = create_in(path_, self.schema, store)
        else:
            ix =  store.Index(path_)
            store = ix.writer()
        self.ix = ix

    def add_document(self, document):
        writer = self.ix.writer()
        writer.add_document(id=document['id'], title=document['title'], content=document['content'])
        writer.commit()

    def search(self, query):
        with self.ix.searcher() as searcher:
            results = searcher.search(query)
            return [{'title': result.fragment['title'], 'content': result.fragment['content']} for result in results]

index = Indexer()
index.create_index()

@app.route('/add', methods=['POST'])
def add_document():
    index.add_document(request.json)
    return jsonify({'message': 'Document added successfully'})

@app.route('/search', methods=['GET'])
def search():
    query = request.args.get('q')
    results = index.search(query)
    return jsonify({'results': results})

if __name__ == '__main__':
    app.run(debug=True)
