import tarfile
import os

def extract_img(img_path):
    def extract_tar(tar_path):
        extract_dir = os.path.splitext(tar_path)[0]
        with tarfile.open(tar_path) as tar:
            tar.extractall(extract_dir)
            tar.close()
        return extract_dir

    def extract_wim(wim_path):
        import shutil
        extract_dir = os.path.splitext(wim_path)[0]
        dump_wim_cmd = f'tools::wimlib-imagex /capture /wimoutput:{extract_dir} {wim_path}'
        os.system(dump_wim_cmd)
        import pathlib
        return str(pathlib.Path(extract_dir).resolve())

    image_formats = ['tar', 'wim']
    img_type = os.path.splitext(img_path)[1].lower()[1:]
    if img_type in image_formats:
        if img_type == 'tar':
            return extract_tar(img_path)
        elif img_type == 'wim':
            return extract_wim(img_path)
    else:
        print(f"Unsupported image type: {img_type}")
        return None
