import argparse
import os
import re

def recursive_search(directory, pattern):
    """Recursively search for occurrences of a regex pattern in a directory and its subdirectories."""
    pattern = re.compile(pattern)
    matches = []
    for root, dirs, files in os.walk(directory):
        for file in files:
            file_path = os.path.join(root, file)
            try:
                with open(file_path, 'r') as f:
                    content = f.read()
                    if pattern.search(content):
                        matches.append((file_path, pattern.findall(content)))
            except Exception as e:
                print(f"Error reading file {file_path}: {e}")
    return matches

def main():
    parser = argparse.ArgumentParser(description="Search for occurrences of a regex pattern in a directory and its subdirectories.")
    parser.add_argument("-d", "--directory", help="directory to search in")
    parser.add_argument("-p", "--pattern", help="regex pattern to search for")
    args = parser.parse_args()
    if not args.directory or not args.pattern:
        parser.print_help()
        return
    matches = recursive_search(args.directory, args.pattern)
    if matches:
        for file_path, matches_list in matches:
            print(f"File: {file_path}")
            for match in matches_list:
                print(f"  {match}")
    else:
        print("No matches found.")

if __name__ == "__main__":
    main()
