def extract_files(archive, temp_dir, overwrite=True):
    if os.path.exists(temp_dir):
        if os.path.isdir(temp_dir):
            if overwrite:
                shutil.rmtree(temp_dir)
            else:
                raise FileExistsError("Target directory already exists and overwriting is disabled")
        else:
            raise NotADirectoryError("Target is not a directory")
    os.makedirs(temp_dir, exist_ok=True)

    archive_path, archive_extension = os.path.splitext(archive)
    if archive_extension.lower() == '.rar':
        archive = rarfile.RarFile(archive)
    elif archive_extension.lower() in ['.tar', '.tar.gz', '.tar.bz2', '.tar.xz']:
        if archive_extension.lower() == '.tar':
            file_extension = 'tar'
        elif archive_extension.lower() == '.tar.gz':
            file_extension = 'gztar'
        elif archive_extension.lower() == '.tar.bz2':
            file_extension = 'bz2'
        elif archive_extension.lower() == '.tar.xz':
            file_extension = 'xz'
        archive = tarfile.open(archive, 'r:' + file_extension)
    else:
        raise ValueError("Unsupported archive type")

    archive.extractall(temp_dir)

    return temp_dir

