    def __init__(self, source_dir, target_dir, archive_extension='tar.gz'):
        self.source_dir = source_dir
        self.target_dir = target_dir
        self.archive_extension = archive_extension

    def create_archive(self):
        try:
            timestamp = datetime.datetime.now().strftime('%Y%m%d_%H%M%S')
            archive_name = f"backup_{timestamp}.{self.archive_extension}"
            archive_path = os.path.join(self.target_dir, archive_name)

            with tarfile.open(archive_path, 'w:' + self.archive_extension.lstrip('gz'), compresslevel=9) as tar:
                for root, dirs, files in os.walk(self.source_dir):
                    for file in files:
                        file_path = os.path.join(root, file)
                        rel_path = os.path.relpath(file_path, self.source_dir)
                        tar.add(file_path, rel_path)

            logging.info(f"Backup created: {archive_path}")
            return archive_path
        except Exception as e:
            logging.error(f"An error occurred while creating backup: {str(e)}")
            return None

    def get_available_space(self):
        disk_space = self.target_dir
        return get_size(disk_space) / (1024 * 1024 * 1024)

def get_size(start_path, total=0):
    for dirpath, dirnames, filenames in os.walk(start_path):
        for f in filenames:
            fp = os.path.join(dirpath, f)
            total += os.path.getsize(fp)
    return total


if __name__ == "__main__":
