import containerregistry.client.errors
import containerregistry.builder

def extract_image_tars(image_uri, output_folder):
    try:
        image = containerregistry.builder.ContainerRegistryImage(image_uri)
        response = image.get_layers()
        for layer in response['images']:
            layer_image = containerregistry.client.session.get(layer['image'])
            for tarball in layer_image.content.discover():
                out_path = os.path.join(output_folder, tarball._media)
                Path(out_path).parent.mkdir(parents=True, exist_ok=True)
                layer_image.download(tarball._media, out_path)
                with tarfile.open(out_path, 'r:gz') as tar:
                    tar.extractall(out_path)
                    for member in tar.getmembers():
                        if member.name.endswith('/'):
                            os.chmod(member.name, 0o755)

    except containerregistry.client.errors.ImageNotFoundError as e:
        print(f"Image not found: {e}")
    except containerregistry.client.errors.RegistryConnectError as e:
        print(f"Error connecting to registry: {e}")
    except Exception as e:
        print(f"Error extracting image layers: {e}")

def main():
    image_uri = 'docker://docker.io/library/alpine:latest'
    output_folder = 'extracted_images'
    extract_image_tars(image_uri, output_folder)

if __name__ == '__main__':
