def calculate_files_size(directory):
    """Calculate the total size of all files in a given directory."""
    total_size = 0
    for dirpath, dirnames, filenames in os.walk(directory):
        for f in filenames:
            fp = os.path.join(dirpath, f)
            total_size += os.path.getsize(fp)
    return total_size

def get_large_files(directory, threshold):
    """Return a list of files greater than the given size in a particular directory."""
    large_files = []
    for root, dirs, files in os.walk(directory):
        for f in files:
            file_path = os.path.join(root, f)
            file_size = os.path.getsize(file_path)
            if file_size > threshold:
                large_files.append({
                    'path': file_path,
                   'size': file_size
                })
        return large_files

def apply_permissions(file_list, action):
    """Apply permissions to a list of files."""
    if action not in ['chmod','move', 'delete']:
        print("Invalid action. Choose from: 'chmod','move', 'delete'.")
    else:
        for file in file_list:
            if action == 'chmod':
                os.chmod(file['path'], stat.S_IRUSR | stat.S_IWUSR | stat.S_IXUSR)
            elif action == 'delete':
                response = input(f"Are you sure you want to delete {file['path']}? (y/n): ")
                if response.lower() == 'y':
                    try:
                        os.remove(file['path'])
                        print(f"File {file['path']} deleted successfully.")
                    except Exception as e:
                        print(f"Error deleting file {file['path']}: {e}")
                else:
                    print(f"Deletion of {file['path']} cancelled.")

def main():
    parser = argparse.ArgumentParser(description='Disk Usage Analyzer and File Manager')
    parser.add_argument('--directory', '-d', help='directory to scan', required=True)
    parser.add_argument('--size_threshold', '-s', type=int, help='size threshold (in bytes)', required=True)
    parser.add_argument('--action', '-a', choices=['chmod','move', 'delete'], help='action to perform on large files')
