import os
import requests
from bs4 import BeautifulSoup
import pickle

# Define constants
HEADERS = {
    'User-Agent': 'Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/91.0.4472.164 Safari/537.36'
}

def download_url(url):
    """Downloads the content of the given URL."""
    try:
        response = requests.get(url, headers=HEADERS)
        response.raise_for_status()  # Raise an exception for bad status codes
        return response.text
    except requests.RequestException as e:
        print(f"Error downloading {url}: {e}")
        return None

def parse_page(html, url):
    """Parses the given HTML page and extracts links to other pages."""
    soup = BeautifulSoup(html, 'html.parser')
    return [a.get('href') for a in soup.find_all('a') if a.get('href') and a.get('href').startswith('/')]

def follow_links(url, max_pages, crawled, max_depth):
    """Follows links and downloads pages recursively."""
    queue = [url]
    while queue and max_depth > 0:
        current_url = queue.pop(0)
        if current_url not in crawled:
            page_data = download_url(current_url)
            if page_data is not None:
                crawled.add(current_url)
                links = parse_page(page_data, current_url)
                for link in links:
                    queue.append(link)
                if len(queue) > max_pages:
                    return
                max_depth -= 1

def save_crawled_pages(crawled):
    """Saves the crawled pages to a pickle file."""
    with open('crawled_pages.pkl', 'wb') as f:
        pickle.dump(crawled, f)

if __name__ == '__main__':
    crawled = set()
    follow_links('https://example.com', 100, crawled, 5)
    save_crawled_pages(crawled)
