    """
    Load configuration from a file.

    Args:
    file_name (str): Name of the file to load.
    file_extension (str): File extension of the file to load.
    defaults (dict): Default configuration values if file does not exist or is invalid.

    Returns:
    dict: Configuration settings.
    """

    config_file = f"{file_name}.{file_extension}"
    base_dir = os.path.join(os.path.dirname(__file__), 'config')

    file_path = os.path.join(base_dir, config_file)

    if file_extension == 'yaml' or file_extension == 'yml':
        try:
            with open(file_path, 'r') as file:
                return yaml.safe_load(file)
        except FileNotFoundError:
            return defaults
        except yaml.YAMLError as e:
            print(f"Error parsing YAML file: {e}")
            return defaults

    elif file_extension == 'json':
        try:
            with open(file_path, 'r') as file:
                return json.load(file)
        except FileNotFoundError:
            return defaults
        except json.JSONDecodeError as e:
            print(f"Error parsing JSON file: {e}")
            return defaults

    elif file_extension == 'toml':
        try:
            with open(file_path, 'r') as file:
                return toml.load(file)
        except FileNotFoundError:
            return defaults
        except toml.TomlDecodeError as e:
            print(f"Error parsing TOML file: {e}")
            return defaults

