class ArchiveExtractor:
    """A class that provides a simple interface to extract archives using 7-Zip or other archive programs."""

    def __init__(self, format=None, bin_path=None):
        if format not in ['zip', 'rar', 'tar', 'tar.gz', 'tar.bz2', 'rar']:
            format = ''
        if bin_path:
            self.bin_path = bin_path
        elif format == '7z':
            self.bin_path = '7z'
        elif format == 'zip':
            self.bin_path = 'unzip'
        elif format == 'rar':
            self.bin_path = 'unrar'
        elif format == 'tar':
            self.bin_path = 'tar'
        elif format == 'tar.gz':
            self.bin_path = 'tar'
        elif format == 'tar.bz2':
            self.bin_path = 'tar'
        else:
            self.bin_path = None

        self.format = format

    def extract(self, archive_path, output_dir):
        """Extracts an archive to the specified directory."""
        command = f'{self.bin_path} x -o{output_dir} {archive_path}'
        subprocess.run(command, shell=True, check=True)
        print(f'Archive {archive_path} has been successfully extracted to {output_dir}')

class SevenZipExtractor(ArchiveExtractor):
    """A class that provides a simple interface to extract archives using the 7-Zip program."""

    def __init__(self, bin_path=None):
