import tempfile
import pefile
import libwim
from imguntar import ImgTar

class DiskImageExtractor:
    def __init__(self, image_path):
        self.image_path = image_path

    def extract_iso(self, output_dir):
        if self.image_path.endswith('.iso'):
            with open(self.image_path, 'rb') as iso_file:
                with tempfile.NamedTemporaryFile(mode='wb') as tmp_file:
                    shutil.copyfileobj(iso_file, tmp_file)
                    tmp_file.seek(0)
                    imgtar = ImgTar(tmp_file)
                    imgtar.extractall(output_dir)
        else:
            raise ValueError("Unsupported image type: cannot extract ISO")

    def extract_wim(self, output_dir):
        wim_file = libwim.WIMFile(self.image_path)
        for entry in wim_file:
            print(entry.name)
            with tempfile.NamedTemporaryFile(mode='wb') as tmp_file:
                tmp_file.write(entry.data)
                tmp_file.seek(0)
                output_path = os.path.join(output_dir, entry.name)
                if entry.name.endswith('.app'):
                    with pefile.PE(tmp_file.name) as pe:
                        if hasattr(pe, 'DIRECTORY_ENTRY_RESOURCE'):
                            print("Extracting resources from PE...")
                            for resource in pe.DIRECTORY_ENTRY_RESOURCE.entries:
                                for resource_type in resource.directory.entries:
                                    for resource_id in resource_type(directory.entries):
                                        for data in resource_id.directory.entries:
                                            with open(output_path + '.rsrc', 'ab') as f:
                                                f.write(data.data.struct.getData())
                        else:
                            shutil.copyfileobj(tmp_file, open(output_path, 'wb'))
                else:
                    shutil.copyfileobj(tmp_file, open(output_path, 'wb'))

def main():
    if len(sys.argv)!= 3:
        print("Usage: imgextract <image_file> <output_dir>")
        sys.exit(1)

    image_path = sys.argv[1]
    output_dir = sys.argv[2]

    if not os.path.exists(image_path):
        print("Error: image file does not exist")
        sys.exit(1)

    extractor = DiskImageExtractor(image_path)
    if image_path.endswith('.wim'):
        extractor.extract_wim(output_dir)
    else:
        extractor.extract_iso(output_dir)

if __name__ == "__main__":
    import sys
    main()
