import os
import shutil

def remove_temp_files(directory, extensions=None, age=None):
    """
    Remove temporary files from a specified directory or its subdirectories.

    Args:
        directory (str): The directory to search for temporary files.
        extensions (list, optional): File extensions to consider as temporary files. Defaults to ['.tmp', '.tmp.bak', '.tmp~', 'tmp', '~$'].
        age (int, optional): Age of the file in days to consider as temporary. Defaults to None.
    """
    if directory is None:
        directory = os.getcwd()

    if not os.path.exists(directory):
        raise ValueError(f"The directory '{directory}' does not exist.")

    temp_extensions = extensions if extensions else ['.tmp', '.tmp.bak', '.tmp~', 'tmp', '~$']
    temp_files = []

    for root, dirs, files in os.walk(directory):
        for file in files:
            if os.path.splitext(file)[1].lower() in [ext.lower() for ext in temp_extensions]:
                temp_files.append(os.path.join(root, file))
            if age and os.path.getmtime(os.path.join(root, file)) < (datetime.datetime.now() - datetime.timedelta(days=age)).timestamp():
                temp_files.append(os.path.join(root, file))

    return temp_files

def main():
    directory = '/path/to/your/directory'
    temp_files = remove_temp_files(directory)
    for file in temp_files:
        try:
            os.remove(file)
            print(f"Removed {file}")
        except OSError as e:
            print(f"Error removing file {file}: {e}")

