import subprocess
import os
import sys
import argparse
import shutil

class BuildSystem:
    def __init__(self, source_code_dir, build_dir):
        self.source_code_dir = source_code_dir
        self.build_dir = build_dir

    def compile_c_code(self, file_name):
        command = f"gcc -o {self.build_dir}/{file_name} {self.source_code_dir}/{file_name}"
        try:
            subprocess.run(command, shell=True, check=True)
        except subprocess.CalledProcessError as e:
            print(f"Compilation failed with error code {e.returncode}")
            sys.exit(1)

    def compile_cpp_code(self, file_name):
        command = f"g++ -o {self.build_dir}/{file_name} {self.source_code_dir}/{file_name}"
        try:
            subprocess.run(command, shell=True, check=True)
        except subprocess.CalledProcessError as e:
            print(f"Compilation failed with error code {e.returncode}")
            sys.exit(1)

    def compile_java_code(self, file_name):
        command = f"javac {self.source_code_dir}/{file_name}"
        try:
            subprocess.run(command, shell=True, check=True)
        except subprocess.CalledProcessError as e:
            print(f"Compilation failed with error code {e.returncode}")
            sys.exit(1)

    def build_project(self, file_name):
        if file_name.endswith(('.c', '.cpp')):
            self.compile_c_code(file_name)
            if os.path.exists(os.path.join(self.build_dir, file_name.split('.')[0])):
                shutil.copytree(os.path.join(self.source_code_dir, f"{file_name.split('.')[0]}"), os.path.join(self.build_dir, f"{file_name.split('.')[0]}"))
                shutil.copy(os.path.join(self.source_code_dir, f"{file_name}"), os.path.join(self.build_dir, f"{file_name.split('.')[0]}/{file_name}"))
        elif file_name.endswith('.java'):
            self.compile_java_code(file_name)
        else:
            print("Unsupported file type")


def main():
    parser = argparse.ArgumentParser(description='Automated Build System')
    parser.add_argument('file_name', help='The name of the source code file')
    args = parser.parse_args()
    build_system = BuildSystem('src', 'build')
    build_system.build_project(args.file_name)


if __name__ == '__main__':
    main()
```

