        sources =''.join([os.path.basename(f).replace('.o', '') for f in config['sources']['sources']['main']])
        command = f'gcc {sources} {libs} -o {output_file}'
        commands.append(command)
    return commands

def build_project(config):
    """
    Compiles source code into executables based on the provided configuration.
    """
    build_commands = get_build_commands(config)
    for command in build_commands:
        subprocess.run(command, shell=True, check=True)

def build_config(config_path):
    """
    Builds a project based on a configuration file.
    """
    with open(config_path, 'r') as f:
        config = eval(f.read())
    build_project(config)

def main():
    config_path = 'build.config'
    build_config(config_path)

class Config:
    def __init__(self):
        self.sources = self._get_sources()
        self.build_commands = []

    def _get_sources(self):
        sources = {}
        for source_type, paths in [
            ('sources','src'),
            ('resources','res')
        ]:
            sources[source_type] = {}
            for path in pathlib.Path(paths).rglob('*.c'):
                source_type = 'object' if path.stem.endswith('c') else None
                if source_type is not None:
                    source_name = path.stem.split('.')[0]
                    if source_name in sources[source_type]:
                        sources[source_type][source_name].append(str(path))
                    else:
                        sources[source_type][source_name] = [str(path)]
        return sources

if __name__ == '__main__':
    main()
