import argparse
import os

def get_filename(filename):
    """Return the filename without directory and extension"""
    return os.path.splitext(os.path.basename(filename))[0]

def add_ext(filename, new_extension):
    """Add a new extension to the filename"""
    name, _ = os.path.splitext(os.path.basename(filename))
    return f"{name}{new_extension}"

def rename_file(filename, new_name):
    """Rename a file with a new name"""
    try:
        new_path = os.path.join(os.path.dirname(filename), new_name)
        os.rename(filename, new_path)
    except Exception as e:
        print(f"Error renaming {filename}: {e}")

def change_permissions(filename, permissions):
    """Change permissions of a file"""
    try:
        os.chmod(filename, permissions)
    except Exception as e:
        print(f"Error changing permission of {filename}: {e}")

def main():
    parser = argparse.ArgumentParser(description="Bulk rename files")
    parser.add_argument("-d", "--directory", help="Directory containing the files to rename", required=True)
    parser.add_argument("-s", "--search", help="Search pattern in filename (wildcards allowed)", default="")
    parser.add_argument("-r", "--replace", help="String to replace in filename (wildcards allowed)", default="")
    parser.add_argument("-x", "--extension", help="New extension for the files", default=".txt")
    parser.add_argument("-p", "--permissions", help="Chmod permissions for the files (in decimal format)", type=int, default=0o644)
    group = parser.add_mutually_exclusive_group(required=True)
    group.add_argument("-c", "--count", action="store_true", help="Only count the files that match the criteria")
    group.add_argument("-n", "--dry-run", action="store_true", help="Do not rename the files, only simulate the process")
    args = parser.parse_args()

    files = [f for f in os.listdir(args.directory) if os.path.isfile(os.path.join(args.directory, f))]

    count = 0
    for filename in files:
        if args.count:
            if (args.search and args.replace and args.search not in filename) or (args.search and filename.find(args.search) > 0) or args.search == "" and filename.find(args.replace) > 0:
                continue
            count += 1
        else:
            if not args.count and (args.search!= "" and not (args.search in filename)) or (args.replace!= "" and filename.find(args.replace) < 0):
                continue
            new_name = add_ext(filename, args.extension)
            if new_name!= filename:
                rename_file(os.path.join(args.directory, filename), new_name)
                if not args.dry_run:
                    change_permissions(os.path.join(args.directory, new_name), args.permissions)
            count += 1

    if args.count:
        print(f"Files found: {count}")

if __name__ == "__main__":
    main()
