import os
import hashlib
import urllib.request
from typing import Dict

class CacheManager:
    def __init__(self, cache_dir: str):
        self.cache_dir = cache_dir
        self.cache_contents = {}

    def _create_cache_dir(self):
        if not os.path.exists(self.cache_dir):
            os.makedirs(self.cache_dir)

    def _get_cache_file_path(self, key: str) -> str:
        return os.path.join(self.cache_dir, f"{hashlib.sha256(key.encode()).hexdigest()}.bin")

    def get(self, key: str) -> bytes:
        cache_file_path = self._get_cache_file_path(key)
        if os.path.exists(cache_file_path):
            with open(cache_file_path, 'rb') as f:
                return f.read()
        return None

    def put(self, key: str, value: bytes):
        cache_file_path = self._get_cache_file_path(key)
        with open(cache_file_path, 'wb') as f:
            f.write(value)

class AssetManager:
    def __init__(self, cache_manager: CacheManager):
        self.cache_manager = cache_manager

    def download(self, url: str) -> bytes:
        response = urllib.request.urlopen(url)
        value = response.read()
        return self.cache_manager.put(url, value)

    def get(self, url: str) -> bytes:
        return self.cache_manager.get(url)

    def has(self, url: str) -> bool:
        return self.cache_manager.get(url) is not None

class MediaLoader:
    def __init__(self, asset_manager: AssetManager):
        self.asset_manager = asset_manager

    def _load(self, url: str) -> bytes:
        if self.asset_manager.has(url):
            return self.asset_manager.get(url)
        return self.asset_manager.download(url)

    def load(self, url: str) -> bytes:
        value = self._load(url)
        return value

def main():
