class CodeAnalyzer:
    def __init__(self, root_path):
        self.root_path = root_path
        self.coverage = coverage(program=['--include', self.root_path])
        self.coverage.start()
        self.annotations = {}

    def identify_uncovered_functions(self):
        uncovered_functions = set()
        for file_name in self.get_all_files():
            with open(file_name, 'r') as file:
                for num, line in enumerate(file):
                    if line.strip().startswith('def'):
                        function_name = line.split()[1]
                        if not self.coveragefunctions.__containsfunction__(function_name):
                            uncovered_functions.add((file_name, num))
        return uncovered_functions

    def get_all_files(self):
        files = []
        for root, dirs, file_names in os.walk(self.root_path):
            for file_name in file_names:
                files.append(os.path.join(root, file_name))
        return files

    def save_annotations(self, uncovered_functions, permissions):
        for file_name, line_number in uncovered_functions:
            file_path = os.path.relpath(file_name, self.root_path)
            with open(file_path, 'r') as file:
                lines = file.readlines()
            if (file_name, line_number) not in self.annotations.keys():
                self.annotations[(file_name, line_number)] = {
                    "permissions": permissions[file_path]
                }
            lines[line_number] = f'# TODO: {permissions[file_path]}\n' + lines[line_number]
            with open(file_path, 'w') as file:
                file.writelines(lines)

    def run(self, permissions):
        uncovered_functions = self.identify_uncovered_functions()
        self.save_annotations(uncovered_functions, permissions)


def main():
