    return gzip.GzipFile(fileobj=BytesIO(data)).read().decode('utf-8')

def extract_zip_bytes(data):
    return zipfile.ZipFile(fileobj=BytesIO(data)).namelist()[0]

def extract_rar_bytes(data):
