        if self.archive_format == 'zip':
            with zipfile.ZipFile(self._get_archive_path(archive_name), 'w', compression=self.get_compression_type(compression_level)) as zip_file:
                for root, dirs, files in os.walk(source_dir):
                    for file in files:
