class Leaderboard:
    def __init__(self):
        self.players = {}

    def add_player(self, name, score, rank):
        if name in self.players:
            self.players[name]['score'] = max(self.players[name]['score'], score)
            self.players[name]['rank'] = self.calculate_rank(self.players, name)
        else:
            self.players[name] = {'score': score, 'rank': self.calculate_rank(self.players, name)}

    def calculate_rank(self, players, name):
        sorted_players = sorted(players.items(), key=lambda x: x[1]['score'], reverse=True)
        rank = 1
        for player in sorted_players:
            if player[0]!= name:
                rank += 1
        return rank

