class BackupSystem:
    def __init__(self):
        self.source_path = ''
        self.destination_path = ''
        self.file_name = ''

    def set_source_path(self, path):
        if os.path.exists(path):
            self.source_path = path
        else:
            print(f"The specified source path {path} does not exist.")

    def set_destination_path(self, path):
        if os.path.exists(os.path.dirname(path)):
            self.destination_path = path
        else:
            print(f"The specified destination folder {os.path.dirname(path)} does not exist.")

    def set_file_name(self, name):
        self.file_name = name

    def compress(self):
        try:
            with tarfile.open(self.file_name + '.tar.gz', 'w:gz') as tar:
                tar.add(self.source_path)
            print(f"Backup created successfully in {self.file_name + '.tar.gz'}.")
        except Exception as e:
            print(f"Error occurred: {e}")

    def extract(self):
        try:
            with tarfile.open(self.file_name + '.tar.gz', 'r:gz') as tar:
                tar.extractall(self.destination_path)
            print(f"Backup extracted successfully to {self.destination_path}.")
        except Exception as e:
            print(f"Error occurred: {e}")

def main():
    parser = argparse.ArgumentParser(description='Backup and extract files')
    parser.add_argument('-c', '--create', action='store_true', help='Create a backup')
    parser.add_argument('-i', '--input', required=True, help='Source file or folder path')
    parser.add_argument('-o', '--output', required=True, help='Output file name')
    parser.add_argument('-e', '--extract', action='store_true', help='Extract a backup')
    args = parser.parse_args()

    backup = BackupSystem()
    backup.set_file_name(args.output)

    if args.create:
        backup.set_source_path(args.input)
        threading.Thread(target=backup.compress).start()
    elif args.extract:
        backup.set_destination_path(args.input)
        threading.Thread(target=backup.extract).start()
    else:
        print("Specify either -c or -e option.")

if __name__ == "__main__":
