import requests
from bs4 import BeautifulSoup
from collections import deque
from urllib.parse import urljoin

START_URL = 'http://example.com'

def get_links(url):
    try:
        resp = requests.get(url)
        resp.raise_for_status()  # Raise a HTTPError for bad status codes
    except requests.exceptions.RequestException as e:
        print(f"Exception occurred while fetching {url}: {e}")
        return []

    soup = BeautifulSoup(resp.text, 'html.parser')
    return [link.get('href') for link in soup.find_all('a')]

def crawl(url):
    queue = deque([START_URL])
    visited = set()

    while queue:
        current_url = queue.popleft()
        if current_url not in visited:
            visited.add(current_url)
            try:
                links = get_links(current_url)
                links = [urljoin(current_url, link) for link in links if link is not None]
                links = [link for link in links if link.startswith('http')]

                for link in links:
                    if link not in visited:
                        queue.append(link)
            except requests.exceptions.RequestException as e:
                print(f"Exception occurred while fetching {current_url}: {e}")

crawl(START_URL)
