import tarfile
import zipfile
import rarfile
from pathlib import Path
import shutil

def extract_archive(filename):
    """
    Extracts and returns the contents of a given archive.

    Args:
        filename (str): The path to the compressed archive.

    Returns:
        list: A list of strings representing the extracted file paths.
    """

    if not Path(filename).is_file():
        raise FileNotFoundError(f"The file {filename} does not exist.")

    # Try to determine the archive type
    try:
        with open(filename, 'rb') as f:
            magic = f.read(2)
            if magic == b'\x1f\x8b':  # Gzip
                return extract_gzip(filename)
            elif magic == b'\x50\x4b':  # Zip
                return extract_zip(filename)
            elif magic == b'\x52\x61':  # Rar
                return extract_rar(filename)
            elif magic == b'\x75\x73\x74\x20':  # Tar
                return extract_tar(filename)
            else:
                raise RuntimeError("Unsupported archive type.")
    except Exception as e:
        raise RuntimeError(f"Error determining archive type: {str(e)}")

def extract_gzip(filename):
    try:
        with tarfile.open(filename, 'r:gz') as tar:
            return [f.path for f in tar.getmembers()]
    except Exception as e:
        raise RuntimeError(f"Error extracting gzip archive: {str(e)}.")

def extract_zip(filename):
    try:
        with zipfile.ZipFile(filename, 'r') as zip_ref:
            return [f.filename for f in zip_ref.infolist()]
    except Exception as e:
        raise RuntimeError(f"Error extracting zip archive: {str(e)}")

def extract_rar(filename):
    try:
        with rarfile.RarFile(filename, 'r') as rar_file:
            return [f.filename for f in rar_file.infolist()]
    except Exception as e:
        raise RuntimeError(f"Error extracting rar archive: {str(e)}")

def extract_tar(filename):
    try:
        with tarfile.open(filename, 'r') as tar:
            return [f.path for f in tar.getmembers()]
    except Exception as e:
        raise RuntimeError(f"Error extracting tar archive: {str(e)}")

def main():
    filename = input("Enter the archive file path: ")
    try:
        extracted_files = extract_archive(filename)
        print("Extracted Files:")
        for file in extracted_files:
            print(file)
    except RuntimeError as e:
        print(f"Error: {str(e)}")

if __name__ == "__main__":
    main()
