import os
import argparse

class FileSearcher:
    def __init__(self, root_dir, filename, search_text):
        self.root_dir = root_dir
        self.filename = filename
        self.search_text = search_text

    def search_files(self):
        matching_files = []
        for root, dirs, files in os.walk(self.root_dir):
            for file in files:
                if file == self.filename:
                    file_path = os.path.join(root, file)
                    try:
                        with open(file_path, 'r') as f:
                            contents = f.read()
                            if self.search_text in contents:
                                matching_files.append((file_path, contents))
                    except Exception as e:
                        print(f"Error reading file {file_path}: {e}")
        return matching_files

def main():
    parser = argparse.ArgumentParser(description="Search for files by name and content.")
    parser.add_argument("-d", "--dir", help="Directory to search in", required=True)
    parser.add_argument("filename", help="File to search for")
    parser.add_argument("-s", "--search", help="Text to search in the file", required=True)
    args = parser.parse_args()

    searcher = FileSearcher(args.dir, args.filename, args.search)
    results = searcher.search_files()

    if results:
        print("Matching files and contents:")
        for file_path, contents in results:
            print(f"File: {file_path}")
            print(contents)
    else:
        print("No matching files found.")

if __name__ == "__main__":
    main()
