import urllib.parse
from urllib.parse import urlparse

def find_broken_links(url):
    try:
        response = requests.get(url)
        response.raise_for_status()
    except requests.exceptions.RequestException as e:
        print(f"Request failed: {e}")
        return []

    soup = BeautifulSoup(response.text, 'html.parser')
    links = soup.find_all('a')

    broken_links = set()

    for link in links:
        href = link.get('href')
        if href:
            absolute_url = urllib.parse.urljoin(url, href)
            try:
                response = requests.head(absolute_url)
                response.raise_for_status()
                broken_links.discard(absolute_url)  # found an active link
            except requests.exceptions.RequestException:
                broken_links.add(absolute_url)  # link is broken

    return broken_links

def get_top_domain(url):
    """Returns the top domain from the given URL as a string."""
    return urlparse(url).netloc.split('?')[0].lower()

def print_broken_links(url):
    broken_links = find_broken_links(url)

    # Organize broken links by top domain
    organized_broken_links = {}
    for link in broken_links:
        top_domain = get_top_domain(link)
        if top_domain in organized_broken_links:
            organized_broken_links[top_domain].append(link)
        else:
            organized_broken_links[top_domain] = [link]

    for domain, broken in organized_broken_links.items():
        print(f"Broken links for {domain}:")
        for link in broken:
            print(f"* {link}")
        print()

if __name__ == "__main__":
    url = input("Enter the URL: ")
    print_broken_links(url)
```

This code correctly checks anchor tags for valid and broken links using the requests library. It then organizes the broken links by top domain for easier identification.

