        self.snippets = {}

    def generate_id(self):
        return md5.new(str(datetime.now()).encode()).hexdigest()

class FlaskPastebin(Flask):
    def __init__(self):
        super().__init__('pastebin')
        self.pastebin = Pastebin()

    def save_snippet(self, data, user_provided_id=None):
        id = user_provided_id or self.pastebin.generate_id()
        self.pastebin.snippets[id] = {'data': data, 'created': datetime.now()}
        return jsonify({'id': id, 'key': id})

    def get_snippet(self, id):
        snippet = self.pastebin.snippets.get(id)
        if snippet:
            return jsonify({'id': id, 'data': snippet['data'], 'created': str(snippet['created'])})
        return jsonify({'error': 'Snippet not found'}), 404

def create_app():
    app = FlaskPastebin()

    @app.route('/', methods=['POST'])
    def create_new_snippet():
        data = request.json.get('text', '')
        return app.save_snippet(data)

    @app.route('/<string:id>')
    def view_snippet(id):
        return app.get_snippet(id)

    @app.errorhandler(404)
    def not_found(e):
        return 'Snippet not found', 404

    return app

