    article.views += 1
    article.save()
    return render(request, 'article/detail.html', {'article': article})

def article_create(request):
    if request.method == 'POST':
        form = ArticleForm(request.POST, request.FILES)
        if form.is_valid():
            article = form.save(commit=False)
            article.author = request.user
            article.save()
            return redirect('article_list')
    else:
        form = ArticleForm()
    return render(request, 'article/form.html', {'form': form})

def article_update(request, pk):
    article = get_object_or_404(Article, pk=pk)
    if request.user!= article.author and not request.user.is_superuser:
        raise PermissionDenied
    if request.method == 'POST':
        form = ArticleForm(request.POST, request.FILES, instance=article)
        if form.is_valid():
            form.save()
            return redirect('article_list')
    else:
        form = ArticleForm(instance=article)
    return render(request, 'article/form.html', {'form': form})

def article_delete(request, pk):
    article = get_object_or_404(Article, pk=pk)
    if request.user!= article.author and not request.user.is_superuser:
        raise PermissionDenied
    if request.method == 'POST':
        article.delete()
        return redirect('article_list')
    return render(request, 'article/delete.html', {'article': article})

def article_draft_list(request):
    articles = Article.objects.filter(status='draft')
    return render(request, 'article/draft_list.html', {'articles': articles})

def article_publish(request, pk):
    article = get_object_or_404(Article, pk=pk)
    if request.user!= article.author and not request.user.is_superuser:
        raise PermissionDenied
    article.status = 'published'
    article.save()
    return redirect('article_list')
