    for file in os.listdir(packaging_dir):
        if file.endswith('.jar'):
            name = file.split('.')[0]
            name = name.split('/')[-1]
            if name in dependencies:
                jars.append(os.path.join(packaging_dir, file))
    return jars

def create_zip_file(dependencies, jars, output_filename):
    with tempfile.TemporaryDirectory() as tmp_dir:
        for jar in jars:
            shutil.copy2(jar, tmp_dir)
        with zipfile.ZipFile(output_filename, 'w') as zip_file:
            for file in os.listdir(tmp_dir):
                zip_file.write(os.path.join(tmp_dir, file))

