import types
import typing

def add_type_annotations(file_path: str) -> str:
    try:
        with open(file_path, 'r') as f:
            source = f.read()
    except FileNotFoundError:
        print(f"File {file_path} not found.")
        return ''

    tree = ast.parse(source)
    add_annotations(tree)
    unparse = astunparse.unparse(tree)
    return unparse


def add_annotations(node: ast.AST) -> None:
    if isinstance(node, ast.ClassDef):
        add_annotations(node.body)
        for child in node.body:
            if isinstance(child, ast.FunctionDef):
                for decorator in child.decorator_list:
                    if isinstance(decorator, ast.Name) and decorator.id == 'type':
                        add_function_type_annotations(child)
    elif isinstance(node, ast.FunctionDef):
        add_function_type_annotations(node)
    elif isinstance(node, ast.Module):
        add_annotations(node.body)


def add_function_type_annotations(node: ast.FunctionDef) -> None:
    for arg in node.args.args:
        arg.annotation = ast.Name(Constant=('typing', 'Any'))
    for line in node.body:
        if isinstance(line, ast.Assign):
            if isinstance(line.value, ast.Call):
                if isinstance(line.value.func, ast.Name) and line.value.func.id == 'print':
                    name = str(types.get_function_type(arg.annotation))
                    node.args.type_comment = '# type:'+ str(name)
                elif isinstance(line.value.func, ast.Name) and line.value.func.id == 'input':
                    node.args.type_comment = '# type:'+ str(name)
    for child in node.body:
        add_annotations(child)


def get_function_type(annotation: typing.Any) -> str:
    if isinstance(annotation, ast.Name):
        name = annotation.id
        return f"typing.{name}"
    elif isinstance(annotation, ast.Subscript):
        base_type = get_function_type(annotation.value)
        elts = [get_function_type(expr) for expr in annotation.slice]
        if len(elts) == 1:
            return f"{base_type}[{elts[0]}"
        else:
            return f"{base_type}[{','.join(elts)})"
    elif isinstance(annotation, ast.Call):
        func = annotation.func.id
        func_module = importlib.import_module('typing')
        func_type = getattr(func_module, func)
        return get_function_type(func_type.return_annotation)
    elif isinstance(annotation, (ast.Bytes, ast.Str, ast.List, ast.Tuple, ast.Set, ast.Dict)):
        return str(annotation)

def run_typeshifter(file_path: str):
    src = add_type_annotations(file_path)
    with open(file_path, 'w') as f:
