import os
import stat
import argparse

class FileRenamer:
    def __init__(self, root_dir):
        self.root_dir = root_dir

    def get_files(self, pattern):
        for path, dirs, files in os.walk(self.root_dir):
            for file in files:
                match = True
                for key, value in pattern.items():
                    if not value in file.lower():
                        match = False
                        break
                if match:
                    yield os.path.join(path, file)

    def rename_files(self, new_name_func, pattern):
        for file in self.get_files(pattern):
            new_name = new_name_func(file, pattern)
            os.rename(file, new_name)

    def apply_permissions(self, permissions, pattern):
        for file in self.get_files(pattern):
            mode = 0
            for p in permissions:
                if p.lower() == "read":
                    mode |= stat.S_IRUSR | stat.S_IRGRP | stat.S_IROTH
                elif p.lower() == "write":
                    mode |= stat.S_IWUSR | stat.S_IWGRP | stat.S_IWOTH
                elif p.lower() == "execute":
                    mode |= stat.S_IXUSR | stat.S_IXGRP | stat.S_IXOTH
            os.chmod(file, mode)

def new_name_replace(filename, pattern):
    for key, value in pattern.items():
        filename = filename.replace(key, value)
    return filename

def usage():
    parser = argparse.ArgumentParser(description='Bulk rename files based on user-specified patterns')
    parser.add_argument('-r', '--root_dir', help='root directory to search for files', required=True)
    parser.add_argument('-p', '--pattern', type=dict, help='rename pattern as key-value pairs', required=False)
    parser.add_argument('-n', '--new_name_func', type=type(new_name_replace), help='rename function', required=False, default=new_name_replace)
    parser.add_argument('-e', '--permissions', nargs='*', help='permissions to apply read, write, or execute', required=False)
    args = parser.parse_args()
    return args

def main():
    args = usage()
    renamer = FileRenamer(args.root_dir)
    if args.pattern:
        renamer.rename_files(args.new_name_func, args.pattern)
        if args.permissions:
            renamer.apply_permissions(args.permissions, args.pattern)
    else:
        print('No pattern specified.')

if __name__ == "__main__":
    main()
