def calculate_h2h(team1, team2):
    """Calculate the Head-to-Head (H2H) record between two teams.

    Args:
        team1 (str): Name of the first team.
        team2 (str): Name of the second team.

    Returns:
        dict or str: H2H record in dictionary format if both teams exist, otherwise an empty dictionary.
    """
    h2h = {"team1": team1, "team2": team2, "wins": 0, "loses": 0}

    # Ensure both teams are in the database
    if team1 in team_data and team2 in team_data:
        # Calculate wins and losses
        h2h["wins"] = min(team_data[team1]["wins"], team_data[team2]["wins"])
        h2h["loses"] = max(team_data[team1]["wins"], team_data[team2]["wins"]) - min(team_data[team1]["wins"], team_data[team2]["wins"])

    return h2h

@app.route('/h2h')
def h2h_view():
    team1 = request.args.get('team1', '')
    team2 = request.args.get('team2', '')
    h2h = calculate_h2h(team1, team2)

    # Return H2H record
    if team1 and team2:
