# Receipt format: base64 encoded JSON object (optional: image attachment)
# Example:
# {
#   "store": "Wal-Mart",
#   "total": 42.99,
#   "items": [
#     {
#       "product": "Apple",
#       "price": 1.99,
#       "quantity": 1
#     },
#     {
#       "product": "Banana",
#       "price": 0.99,
#       "quantity": 2
#     }
#   ],
#   "image": "iVBORw0KGg...", // base64 encoded receipt image
#   "timestamp": "2022-07-26T14:30:00"
# }

# Temporary storage for uploaded receipts
receipts = {}

# Parse receipt from base64 encoded JSON object (or attachment)
def parse_receipt(receipt_data):
    try:
        # Decode receipt from base64
        receipt = yaml.safe_load(base64.b64decode(receipt_data, validate=True))
    except (ValueError, TypeError):
        # If invalid or missing receipt data, return None
        return None
    return receipt

# Validate and save receipt (if valid)
def save_receipt(receipt):
    if not receipt or not receipt.get('store') or not receipt.get('total'):
        return False
    timestamp = datetime.datetime.now().strftime("%Y-%m-%dT%H:%M:%S")
    receipt['timestamp'] = timestamp
    receipts[timestamp] = receipt
    return True

@app.route('/submit-receipt', methods=['POST'])
def submit_receipt():
    if'receipt' in request.form:
        receipt = parse_receipt(request.form.get('receipt'))
        if receipt:
            if save_receipt(receipt):
                return jsonify({'message': 'Receipt received!'}), 200
            else:
                return jsonify({'error': 'Invalid receipt'}), 400
        else:
            return jsonify({'error': 'Failed to parse receipt'}), 400
    elif 'image' in request.files:
        receipt = parse_receipt(request.files.get('image').read())
        if receipt:
            if save_receipt(receipt):
                return jsonify({'message': 'Receipt received!'}), 200
            else:
                return jsonify({'error': 'Invalid receipt'}), 400
        else:
            return jsonify({'error': 'Failed to parse receipt'}), 400
    else:
        return jsonify({'error': 'No receipt data provided'}), 400

@app.route('/receipts', methods=['GET'])
def get_receipts():
    return jsonify(receipts)

if __name__ == '__main__':
    app.run(debug=True)
