import tarfile
import os
import shutil

def create_backup(dir_path, backup_root=None, backup_dir="backup"):
    if backup_root is None:
        backup_root = os.path.basename(dir_path)
    backup_path = os.path.join(os.getcwd(), backup_dir)
    os.makedirs(backup_path, exist_ok=True)
    tar_name = os.path.join(backup_path, f"{backup_root}_{os.path.basename(dir_path)}.tar")
    with tarfile.open(tar_name, "w") as tar:
        for root, dirs, files in os.walk(dir_path):
            for file in files:
                tar.add(os.path.join(root, file), arcname=os.path.relpath(os.path.join(root, file), dir_path))
    return tar_name

def remove_duplicates(tar, base_dir):
    tar.addfile_info = {}
    for root, dirs, files in os.walk(base_dir):
        for file in files:
            file_path = os.path.join(root, file)
            tar_info = os.lstat(file_path)
            tar.addinfo = tarfile.TarInfo(file_path.replace(base_dir, ''))
            tar_info.uid = 0
            tar.addinfo.tar_info = tar_info
            if file in tar.addfile_info:
                os.remove(file_path)
            else:
                tar.addfile_info[file] = tar_info

def restore_backup(backup_file, restore_dir):
    with tarfile.open(backup_file, "r") as tar:
        for item in tar.getmembers():
            if os.path.commonpath([backup_file, item.name])!= backup_file:
                file_path = os.path.join(restore_dir, item.name)
                try:
                    directory = os.path.dirname(file_path)
                    os.makedirs(directory, exist_ok=True)
                    tar.extract(item, path=restore_dir)
                except OSError as e:
                    print(f"Error restoring file {item.name}: {e}")

backup_file = create_backup("data")
restore_backup(backup_file, "data")
