import ast
from typing import Dict, List
import inspect

class CodeAnalyzer:
    def __init__(self, filename: str):
        self.filename = filename

    def get_module(self) -> ast.Module:
        with open(self.filename, 'r') as f:
            source = f.read()
            return ast.parse(source)

    def get_coverage(self) -> Dict[str, float]:
        module = self.get_module()
        coverage = {}
        for node in module.body:
            if isinstance(node, ast.FunctionDef):
                if hasattr(node, 'name'):
                    if node.name not in coverage:
                        coverage[node.name] = 0
                    test_lines = inspect.getblock(node.body)
                    total_lines = len(self.get_test_lines(node.name))
                    covered_lines = set(self.get_test_lines(node.name)) & set(inspect.getblock(node.body))
                    coverage[node.name] = len(covered_lines) / total_lines
            elif isinstance(node, ast.ClassDef):
                for subnode in node.body:
                    if isinstance(subnode, ast.FunctionDef):
                        if hasattr(subnode, 'name'):
                            if subnode.name not in coverage:
                                coverage[subnode.name] = 0
                            test_lines = inspect.getblock(subnode.body)
                            total_lines = len(self.get_test_lines(subnode.name))
                            covered_lines = set(self.get_test_lines(subnode.name)) & set(inspect.getblock(subnode.body))
                            coverage[subnode.name] = len(covered_lines) / total_lines
        return coverage

    def suggest_tests(self) -> List[str]:
        coverage = self.get_coverage()
        suggestions = []
        for func, perc in coverage.items():
            if perc < 0.8:
                suggestions.append(f'Low coverage for function: {func}')
        return suggestions

    def generate_test_code(self) -> str:
        suggest_code = ''
        suggestions = self.suggest_tests()
        for suggestion in suggestions:
            print(f'  {'='.join(suggestion.split()[:3])}')
            module_name = f'test_{suggestion.split()[-1]}'
            function_name = suggestion.split()[-1]
            suggest_code += f'''\
def test_{function_name}():
    # TODO: implement test for {function_name}
    pass
            '''
        return suggest_code


    def write_covered_lines(self, func_name: str) -> List[int]:
        with open(self.filename, 'r') as f:
            lines = f.readlines()
        covered_lines = []
        for i, line in enumerate(lines, start=1):
            node = ast.parse(inspect.cleandoc(line).rstrip()).body[0]
            if isinstance(node, ast.Pass):
                if 'pass' in line: covered_lines.append(i)
            elif isinstance(node, ast.Expr) and 'assert' in line:
                covered_lines.append(i)
            elif isinstance(node, ast.Assign):
                covered_lines.append(i)
            else:
                continue
        return covered_lines

    def get_test_lines(self, func_name: str) -> List[int]:
        if inspect.isclass(func_name):
            test_module = f'{func_name}.py'
            if not os.path.exists(test_module):
                test_module = f'test_{func_name}.py'
        else:
            test_module = f'test_{func_name}.py'
        with open(test_module, 'r') as f:
            import re
            return [i for i, line in enumerate(f, start=1) if re.search(r'^def', line)]

def main():
    filename = input("Enter the python module filename: ")
    analyzer = CodeAnalyzer(filename)
    coverage = analyzer.get_coverage()
    print('coverage:')
    for func, perc in coverage.items():
        print(f'  {func}: {perc*100}%')
    suggest_code = analyzer.generate_test_code()
    print(f'suggested code:\n{suggest_code}')

if __name__ == "__main__":
