@app.route('/lookup/<ip>')
@cache.cached(timeout=60)
def lookup(ip):
    try:
        # Use the 'nslookup' command to get the hostname and all associated records
        output = subprocess.check_output(['nslookup', '-type=PTR', ip])
        domain = output.decode('utf-8').split('name =')[-1].strip()
