import os
import sys

def concatenate_files(file_list, output_file):
    """
    Concatenates multiple files into a single output file.

    Args:
    file_list (list): A list of file paths to concatenate.
    output_file (str): The path to the output file.

    Returns:
    str: The path to the output file.
    """
    if not file_list or output_file is None:
        sys.exit("Error: No files or output file specified.")

    try:
        with open(output_file, 'w') as output:
            for file in file_list:
                try:
                    with open(file, 'r') as inp:
                        output.write(inp.read())
                except FileNotFoundError:
                    sys.exit(f"Error: File '{file}' not found.")

    except Exception as e:
        sys.exit(f"Error: {e}")

    return output_file

def main():
    if len(sys.argv) < 3:
        print("Usage: python concatenate_files.py <input_files> <output_file>")
