        self.max_line_length = max_line_length
        self.max_branches = max_branches
        self.issues = []

    def analyze_file(self, file_path: str) -> None:
        try:
            with open(file_path, 'r') as f:
                content = f.read()
            tree = ast.parse(content)
            self._collect_issues(tree, file_path)
        except Exception as e:
            self.issues.append({'file': file_path,'message': str(e)})

    def _collect_issues(self, node, file_path: str, path: str = ''):
        if isinstance(node, ast.Module):
            for child in node.body:
                self._collect_issues(child, file_path, path)
        elif isinstance(node, ast.FunctionDef):
            file_issue = {'file': file_path, 'path': path,'method': node.name}
            if node.body and len(node.body) > self.max_line_length:
