            if node.body and len(node.body) > 0 and any(isinstance(b, ast.If) or isinstance(b, ast.For) or isinstance(b, ast.While) for b in node.body):
                branches = sum(1 for b in node.body if isinstance(b, ast.If) or isinstance(b, ast.For) or isinstance(b, ast.While))
                if branches > self.max_branches:
                    file_issue['issue'] = f'Too many branches: {branches}'
            if file_issue:
                self.issues.append(file_issue)
        elif isinstance(node, ast.If):
            file_issue = {'file': file_path, 'path': path, 'line': node.lineno, 'issue': f'Too long condition'}
            self.issues.append(file_issue)
        elif isinstance(node, ast.FunctionCall):
            if len(node.args) > 5:
