def calculate_nesting_factor(node: ast.AST) -> int:
    """Calculates the nesting factor of a given node."""
    if hasattr(node, 'body'):
        return 1 + sum(calculate_nesting_factor(child) for child in node.body)
    if isinstance(node, (ast.ClassDef, ast.FunctionDef)):
        return 1 + calculate_nesting_factor(node.body)
    return 0

def is_too_complex(node: ast.AST) -> bool:
