import restore_database

def get_website_files(directory):
    files = []
    for filename in glob.glob(os.path.join(directory, '**'), recursive=True):
        if os.path.isfile(filename) and os.path.basename(filename).lower().endswith(('.php', '.js', '.css', '.html', '.txt', '.xml', '.sql')):
            files.append(filename)
    return files

def backup_website_files(directory, zip_file):
    with zipfile.ZipFile(zip_file, 'w') as zip:
        for filename in get_website_files(directory):
            zip.write(filename, arcname=os.path.relpath(filename, directory))

def backup_db_to_zip(db_name):
    backup_location = os.path.join(os.path.dirname(db_name), db_name + '_backup.sql')
    db = backup_database.backup_db_name(db_name, backup_location)
    if db:
        with zipfile.ZipFile('db_backup.zip', 'w') as zip:
            zip.write(backup_location, arcname='backup.sql')

def restore_db_from_zip(zip_file):
    with zipfile.ZipFile(zip_file) as zip:
        zip.extract('backup.sql', os.path.dirname(os.path.join(os.getcwd(), zip_file)))
    restore_database.restore_db('backup.sql', os.path.join(os.getcwd(), zip_file))

def restore_db(zip_file):
    backup_files = []
    with zipfile.ZipFile(zip_file) as zip:
        for filename in zip.namelist():
            if filename.endswith('.sql'):
                filename = filename.replace('.sql', '')
            if filename not in backup_files:
                backup_files.append(filename)
            else:
                filename = os.path.splitext(filename)[0]
                shutil.copyfile(f'{filename}.sql', f'{filename}_backup.sql')

    for filename in backup_files:
        restore_database.restore_db(filename + '.sql', os.path.join(os.getcwd(), zip_file))

def main():
