    backups_directory = 'backups'
    if not os.path.exists(backups_directory):
        os.makedirs(backups_directory)
    zip_filename = 'backup_{}.zip'.format(len([f for f in os.listdir(backups_directory) if f.startswith('backup_')]))
    if os.path.exists(os.path.join(directory, 'wp-config.php')):
        backup_website_files(directory, os.path.join(backups_directory, zip_filename))
        db_name = os.path.join(directory, 'wp-config.php')
        lines = [line.rstrip() for line in open(db_name)]
