        db_name = db_name.split('=')[1].replace("'", '').strip()
        db_backup = zip_filename.replace('.zip', '_db.sql')
        db_zip = 'db_backup.zip'
        export_location = os.path.join(backups_directory, db_backup)
        export_zip_location = os.path.join(backups_directory, db_zip)
        backup_db_to_zip(db_name.split('=')[1].replace("'", '').strip())
