import os
import warnings

class DiskAnalyzer:
    def __init__(self, threshold, root_dir):
        self.threshold = threshold
        self.root_dir = root_dir

    def analyze_disk_usage(self):
        """Analyzes disk usage and returns a list of large files exceeding the threshold."""
        large_files = []
        for root, dirs, files in os.walk(self.root_dir):
            for file in files:
                file_path = os.path.join(root, file)
                file_size = os.path.getsize(file_path)
                if file_size >= self.threshold:
                    large_files.append((file, file_size, file_path))
        return large_files

    def apply_permissions(self, large_files, permission):
        """Applies permissions to large files based on user input."""
        for file, size, path in large_files:
            print(f"File: {file}, Size: {size} bytes, Path: {path}")
            choice = input("Apply permission (y/n): ")
            if choice.lower() == 'y':
                if permission =='read':
                    os.chmod(path, 0o644)
                elif permission == 'write':
                    os.chmod(path, 0o644)
                elif permission == 'delete':
                    response = input("Confirm deletion (y/n): ")
                    if response.lower() == 'y':
                        try:
                            os.remove(path)
                            print(f"Deleted {file}")
                        except OSError as e:
                            print(f"Error deleting {file}: {e}")
                else:
                    print("Invalid permission. Please choose read, write or delete.")
                    continue
            else:
                print(f"Permission denied for {file}")

def main():
    threshold = int(input("Enter the file size threshold in bytes: "))
    root_dir = input("Enter the root directory to analyze: ")
    permissions = input("Enter permission to apply (read, write or delete): ")

    analyzer = DiskAnalyzer(threshold, root_dir)
    large_files = analyzer.analyze_disk_usage()
    if large_files:
        print("Large files:")
        for file, size, path in large_files:
            print(f"File: {file}, Size: {size} bytes, Path: {path}")
        analyzer.apply_permissions(large_files, permissions)
    else:
        print("No large files found.")

if __name__ == "__main__":
