def extract_word_metadata(file_path):
    """Extract metadata from a word document"""
    if os.path.isfile(file_path) and file_path.endswith('.docx'):
        document = Document(file_path)
        metadata = {"author": None, "created": None, "modified": None}
        for paragraph in document.paragraphs:
            text = paragraph.text
            if re.search(r'Author:[\s]*([a-zA-Z0-9\. _-]+)', text):
                metadata["author"] = re.search(r'Author:[\s]*([a-zA-Z0-9\. _-]+)', text).group(1)
            if re.search(r'Date Created:[\s]*([0-9\/\-\:\.]+)', text):
                metadata["created"] = datetime.strptime(re.search(r'Date Created:[\s]*([0-9\/\-\:\.]+)', text).group(1), '%Y/%m/%d %H:%M:%S')
            if re.search(r'Date Modified:[\s]*([0-9\/\-\:\.]+)', text):
                metadata["modified"] = datetime.strptime(re.search(r'Date Modified:[\s]*([0-9\/\-\:\.]+)', text).group(1), '%Y/%m/%d %H:%M:%S').replace(tzinfo=pytz.UTC)
