class JobScheduler:
    def __init__(self, redis_cluster, interval):
        self.redis_cluster = redis_cluster
        self.interval = interval
        self.jobs = []
        self.lock = threading.Lock()

    def add_job(self, job):
        with self.lock:
            self.jobs.append(job)

    def remove_job(self, job_id):
        with self.lock:
            for job in self.jobs:
                if job.job_id == job_id:
                    self.jobs.remove(job)
                    return True
            return False

    def check_job_status(self, job):
        job_status = self.redis_cluster.get_job_status(job.job_id)
        return job_status == b'succeeded' if job_status else False

    def failover(self, job):
        job_status = self.check_job_status(job)
        if not job_status:
            schedule.every(self.interval).seconds.do(job.execute)
        self.redis_cluster.set_job_status(job.job_id, b'scheduled')

